programs.sol:
"""Detect standalone horizontal whitespace, especially after punctuation.

A space merged into a word is not a trigger. A separate space gives a positive
pulse, strongest after a sentence-ending period, weaker after function words,
and sometimes negative after a spaced mathematical operator. Nonbreaking
spaces and longer whitespace tokens have smaller responses. The short state
joins word fragments so abbreviations and sentence endings can be distinguished.
"""
import re

READS = ()
MONTHS = set('january february march april may june july august september '
             'october november december'.split())
MONTH_ABBREVIATIONS = {month[:3] for month in MONTHS} - {'may'}
ABBREVIATIONS = set('fig figs no nos p pp vol ch sec eq eqs cf ref refs al '
                    'mr mrs ms dr prof art vs st jan feb mar apr jun jul '
                    'aug sep sept oct nov dec'.split())
PREPOSITIONS = set('in of at on with for by than about over under between '
                   'into onto before after during through around'.split())
ARTICLES = {'a', 'an', 'the'}
COPULAS = set('is are was were be been being'.split())
CONJUNCTIONS = {'and', 'or', 'but', 'as', 'that', 'which'}
PUNCTUATION = {
    ',': 0.88, ':': 1.53, ';': 1.30,
    ')': 1.53, ']': 1.50, '}': 1.05,
    '"': 1.45, "'": 0.98, '•': 1.36, '§': 0.89,
}


def space_response(previous, word, after_period):
    if not previous:
        return 0.0
    if '\n' in previous or '\r' in previous:
        return 0.62 if previous.rstrip().endswith('.') else 0.0
    if previous.isspace():
        if previous == ' ':
            return 2.05 if after_period else 1.20
        return 0.65 if len(previous) <= 7 else 0.45

    text = previous.strip()
    end = text[-1]
    spaced = previous.startswith(' ')
    lower = text.lower()
    # Quotation marks and closing brackets can follow a sentence's punctuation.
    core = text.rstrip("\"'”’)]}") or text
    if core[-1] in '.!?。？！':
        end = core[-1]
    if end == '.':
        if len(core) > 1 and not core.strip('.'):
            return 2.15 if len(core) <= 4 else 1.65
        if word.lower() in ABBREVIATIONS:
            value = 2.80
        elif word.isdigit():
            value = 4.0 if len(word) == 4 else 3.40
        else:
            value = 3.05 + 0.15 * min(len(word), 7)
        return value - (0.6 if spaced else 0.0)
    if end in '!?':
        return 2.65 - (0.8 if spaced else 0.0)
    if end in '。？！':
        return 1.25
    if end in PUNCTUATION:
        return PUNCTUATION[end] - (0.5 if spaced else 0.0)
    if end in '=+−×≥≤-':
        if spaced:
            return 0.05 if end == '-' else -0.25
        return 1.30 if end == '-' else 0.65
    if end in '/|*<>':
        return 0.33 if spaced else 0.91
    if text.isdigit():
        return 0.65
    if lower in {'to', 'from'}:
        return -0.16
    if lower in PREPOSITIONS:
        return 0.12
    if lower in ARTICLES:
        return 0.47
    if lower in COPULAS:
        return 0.32
    if lower in CONJUNCTIONS:
        return 0.28
    if text.istitle() and lower in MONTHS:
        return 0.93
    if lower in MONTH_ABBREVIATIONS:
        return 0.0
    if len(text) == 1 and text.isalpha():
        return 0.38
    if not text.isascii():
        return 0.32
    return 0.78 if text.isupper() else 0.62


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, word, after_period = '', '', False
    else:
        _, previous, word, after_period = carry
    token = prefix.token_strings[-1]
    value = 0.003
    if token in {' ', '\xa0', '  ', ' \n', '  \n'}:
        response = space_response(previous, word, after_period)
        if token == ' ':
            value = response
        elif token == '\xa0':
            value = (0.8 * response if previous.isspace()
                     else response - 0.7)
            if '\n' in previous:
                value = 0.26
        elif token == '  ':
            value = (0.0 if '\n' in previous else
                     response * (0.4 if previous.endswith('.') else 0.24))
        else:
            value = (response * (0.15 if token == '  \n' else 0.10)
                     if previous.endswith('.') else -0.03)

    # Retain a period's preceding word, and join consecutive word fragments.
    if token.strip(".!?\"'”’)]}"):
        match = re.search(r'[^\W_]+$', token)
        if match:
            fragment = match.group()
            word = (word + fragment if match.start() == 0 and previous
                    and previous[-1].isalnum() else fragment)
        else:
            word = ''
    return (doc, token, word, previous.endswith('.')), float(value)

programs.haiku:
"""Fires on the standalone space token that Qwen writes just before a number (digits are
split one per token, so "in 2005" is "in", " ", "2", "0", "0", "5"). The model cannot see
the number yet, so the program guesses from the word or mark before the space: after a
sentence end or a clause mark, a number is likely next and the component is strongly
on; after a function word or an operator it is off."""

READS = ()

SPACES = (" ", "\xa0")
SENTENCE_END = {".", "?", "!", "..."}
CLAUSE_MARK = {",", ":", ";", ")", "]", "):", "]:", "':", '"', "•", ".,"}
OPERATORS = {"=", "+", "-", "<", ">", "==", "!=", "+=", "×", "–"}
FUNCTION_WORDS = {"of", "in", "to", "at", "from", "by", "on", "with", "about", "than",
                  "and", "or", "the", "a", "is", "be", "for", "as", "over"}
MONTHS = {"January", "February", "March", "April", "May", "June", "July", "August",
          "September", "October", "November", "December"}


def step(carry, prefix, upstream):
    """Activation at this position: about 3 after a full stop, 1 after a clause mark,
    0.7 after a number or month, 0.4 after another word, 0.15 after a function word,
    -0.2 after an operator; 0 when the current token is not a space."""
    if prefix.token_strings[-1] not in SPACES or len(prefix.token_strings) < 2:
        return carry, 0.0
    prev = prefix.token_strings[-2]
    word = prev.strip()
    if prev in SENTENCE_END:
        value = 3.2
    elif prev in CLAUSE_MARK or word in CLAUSE_MARK:
        value = 1.0
    elif word in OPERATORS:
        value = -0.2
    elif word[-1:].isdigit() or word in MONTHS:
        value = 0.7
    elif word == "":
        value = 0.65
    elif word in FUNCTION_WORDS:
        value = 0.15
    else:
        value = 0.4
    return carry, value

programs.luna:
"""Approximate the component's positive signal at spaces after punctuation."""

READS = ()


def step(carry, prefix, upstream):
    if prefix.token_strings[-1] != " ":
        return None, 0.0

    previous = ""
    if (
        len(prefix) > 1
        and prefix.document_ids[-1] == prefix.document_ids[-2]
    ):
        previous = prefix.token_strings[-2]

    punctuation = previous.rstrip()
    if punctuation.endswith("."):
        return None, 3.4
    if punctuation.endswith((":", ";")):
        return None, 1.65
    return None, 0.67

"""Approximate the strong pulses at chat-format control boundaries.

The main responses are tied to message starts, tool handoffs, and thought
delimiters; the closing-message pulse also depends on what just ended.
Ordinary text is left at zero.
"""

READS = ()

CONTROL_PULSES = {
    "<tool_call>": -1.79,
    "<tool_response>": -1.24,
    "</tool_response>": -0.74,
    "</tool_call>": -0.07,
    "<think>": -1.30,
    "</think>": -1.92,
    "<|endoftext|>": 0.025,
}


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]

    if carry is None or document != carry[0]:
        position, previous = 0, None
    else:
        position, previous = carry[1] + 1, carry[2]

    value = CONTROL_PULSES.get(token, 0.0)
    if token == "<|im_start|>":
        value = -0.50 if position == 0 else -1.55
    elif token == "<|im_end|>":
        if previous in ("</tool_call>", "</tool_response>"):
            value = 0.33
        elif previous and any(char.isalpha() for char in previous):
            value = 0.05
        elif previous and any(char.isdigit() for char in previous):
            value = -0.15
        elif previous and any(not char.isalnum() and not char.isspace()
                              for char in previous):
            value = -0.17
        else:
            value = 0.10

    return (document, position, token), float(value)

programs.haiku:
"""A breadth/extent detector. It goes negative on words meaning how wide or far
something reaches: "wide", "broad", "widely", "narrow", "scope", "breadth" (strongest),
and "range", "spread", "span", "spectrum", "vast", "expand", "coverage", "width" (weaker),
in English and Chinese (广, 宽, 广泛, 范围). The word "of" directly after an extent noun
("range of", "scope of", "spread of") is also negative. Everything else is 0."""

READS: tuple[str, ...] = ()

STRONG = {"wide", "widely", "wider", "widest", "widespread", "broad", "broadly", "broader",
          "broadest", "narrow", "narrower", "scope", "breadth"}
WEAK = {"width", "range", "ranges", "ranging", "spectrum", "spread", "spreads", "spreading",
        "span", "spans", "spanning", "vast", "comprehensive", "expand", "expands", "expanded",
        "expanding", "expansion", "expansive", "extensive", "extensively", "coverage",
        "sweeping", "widen", "widening", "broaden", "encompass", "across"}
ZH_STRONG = {"广", "廣", "广泛", "廣泛", "广泛的", "宽", "阔", "范围", "范围内"}
ZH_WEAK = {"博", "覆盖", "涵盖"}
EXTENT_NOUNS = {"range", "scope", "spread", "span", "spectrum", "variety", "expansion",
                "area", "array", "field", "space", "extent", "degree", "breadth", "width"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    word = tok.strip().lstrip("-_.").lower()
    if word in STRONG or word in ZH_STRONG:
        return carry, -3.5
    if word in WEAK or word in ZH_WEAK:
        return carry, -1.2
    if word == "of" and len(prefix.token_strings) > 1:
        if prefix.token_strings[-2].strip().lower() in EXTENT_NOUNS:
            return carry, -1.3
    return carry, 0.0

programs.sol:
"""A relation-word/connector detector, dominated by phrases ending in 'with'.

Compare/connection/interaction words give strong negative responses on
'with'; combination and familiarity words give weaker ones. 'To' responds
more weakly; 'in' and 'of' reverse the sign. A short intervening phrase
weakens the relation cue. Difference/distance words trigger 'from', and
'between' briefly triggers 'and'. Some translations of 'with' are negative
without an English cue. 'Associated' and 'align(ed)' get small positive
responses on their own. State resets at each document boundary.
"""
import re

READS = ()

# Concept, WITH strength, TO strength, stems covering common inflections.
RELATIONS = (
    ('comparison', -7.2, -2.6, 'compare compari comparab contrast contradict'),
    ('relationship', -5.8, -2.4,
     'relation correlat interact communicat overlap intersect collid collis clash'),
    ('relatedness', -4.2, -2.1, 'relat unrelat'),
    ('connection', -5.0, -2.5,
     'connect reconnect interconnect interlink intertwin bond ties parallel'),
    ('agreement', -4.8, -0.6,
     'agree disagree accord consisten inconsisten compatib incompatib conjunct '
     'contact conflict partnership collaboration coordinat coincid sync exchang '
     'alliance reconcil associat'),
    ('combination', -3.7, -0.5,
     'combin merg mix blend fusion integrat coupl pair union joint share sharing '
     'equilibrium interface'),
    ('alignment', -4.0, -0.8,
     'align affiliat match confus congruen conform cooperat collaborat partner'),
    ('engagement', -3.8, -0.5,
     'engag compet fight fought battl disput trad negotiat'),
    ('conversation', -3.3, -1.5,
     'interview convers dialog discuss talk chat meet acquaint contract'),
    ('familiarity', -2.5, -0.1,
     'deal complian comply consult familiar interfer touch'),
    ('similarity', -2.8, -0.9,
     'similar identic equal equival proportion correspond adjacent perpendicular '
     'opposite oppos orthogonal tangent attach bound bind same'),
)
RELATIONS = tuple((name, w, t, tuple(stems.split()))
                  for name, w, t, stems in RELATIONS)

# Distinctive ordinary phrases within these same relation concepts.
WITH = {
    'compared': -6.7, 'associated': -3.2, 'association': -4.7,
    'connection': -6.6, 'agreement': -5.9, 'border': -4.2,
    'line': -1.7, 'keeping': -3.4,
    'together': -2.1, 'along': -0.6, 'work': -1.1, 'working': -1.1,
}
WITH_TRANSLATIONS = {
    '与': -2.15, '與': -2.2, '跟': -1.2, '跟她': -1.0,
    '跟你': -1.1, '跟我': -0.7, '和': -0.18,
    'avec': -1.24, 'com': -0.94, 'con': -0.57, 'с': -0.48,
    'với': -2.0, 'dengan': -1.2, 'mit': -0.17, 'مع': -0.65,
}
WORDS = re.compile(r'[A-Za-z]+|[.,;!?]')


def level(word, connector):
    if connector == 'from':
        if word.startswith('differ'):
            return -2.3 if word == 'different' else -2.7
        if word.startswith(('distinct', 'distinguish', 'separat', 'disconnect')):
            return -1.9
        if word.startswith(('distance', 'isolat')):
            return -1.3
        return -0.75 if word in {'away', 'apart', 'far'} else -0.08
    if word.startswith(('differ', 'distance')):
        return {'with': -3.0, 'to': -1.4, 'in': 1.3, 'of': 0.3}[connector]
    if word == 'tied':
        if connector == 'to':
            return -2.2
        return -3.0 if connector == 'with' else 0.0
    if word.startswith(('close', 'nearest', 'proximity')):
        return -1.7 if connector == 'to' else 0.0
    if word.startswith('link'):
        if connector == 'to':
            return -1.6
        return -4.5 if connector == 'with' else 0.5
    if connector == 'with' and word in WITH:
        return WITH[word]
    if word.startswith(('start', 'begin', 'finish', 'complet', 'fill')):
        return 0.2 if connector == 'with' else 0.0
    if word.startswith(('shareholder', 'tradition', 'trademark', 'closed')):
        return 0.0
    if word == 'according':
        return -0.1 if connector == 'to' else 0.0
    if word in {'order', 'respect', 'regard', 'reference', 'addition'}:
        return -0.35 if connector == 'to' else 0.0
    for name, with_strength, to_strength, stems in RELATIONS:
        if word.startswith(stems):
            if connector == 'with':
                return with_strength
            if connector == 'to':
                return to_strength
            return min(1.0, -0.15 * with_strength)
    return -0.4 if connector == 'with' else 0.0


def phrase_level(history, connector):
    history = re.sub(r'([a-z])([A-Z])', r'\1 \2', history)
    words = WORDS.findall(history.lower())[-6:]
    value = -0.4 if connector == 'with' else 0.0
    for distance, word in enumerate(reversed(words)):
        if word in {'.', ',', ';', '!', '?', 'but'}:
            return value if distance else 0.0
        strength = level(word, connector)
        if not distance:
            value = strength
            if word.startswith(('start', 'begin', 'finish', 'complet', 'fill')):
                return value
            if connector == 'to' and word in {
                    'have', 'has', 'had', 'used', 'due', 'need', 'needs',
                    'want', 'wants', 'try', 'trying', 'able', 'going'}:
                return 0.0
        elif abs(strength) > 1.0:
            faded = strength * 0.84 ** distance
            if abs(faded) > abs(value):
                value = faded
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history, age = ('', 1000) if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = WITH_TRANSLATIONS.get(word, 0.0)
    if (word.isascii() or word in {'с', 'مع'}) and (
            not token[:1].isspace() or token.strip() != word):
        value = 0.0
    if word in {'with', 'to', 'from', 'in', 'of'}:
        value = phrase_level(history, word)
    elif word == 'and':
        value = -2.4 * max(0.0, 1.0 - max(0, age - 2) / 13.0) ** 1.5
    elif word == 'associated':
        value = 0.67
    elif word in {'align', 'aligned'}:
        value = 0.55
    age = 0 if 'between' in word else age + 1
    return (doc, (history + token)[-160:], age), float(value)

"""A current-word approximation to a questions-and-reading-tasks cue.

Options, questions, blanks, passages and prompts activate it. Definite
references ('the question', 'this passage', etc.) strengthen the response.
Reading comprehension is especially strong. Weaker cues name dialogue,
reading units, choices, and exercises. Other tokens get zero; the detector
is lexical, so matching identifiers also respond. Only the previous token
is retained, and this state is reset between documents.
"""
READS = ()
DEFINITE = {'the', 'this', 'these', 'each', 'following', 'first', 'second',
            'third', 'next', 'last'}
DIALOGUE = {'dialog', 'dialogue', 'conversation', 'conversations'}
READING_UNITS = {'paragraph', 'paragraphs', 'excerpt', 'excerpts', 'sentence',
                 'sentences', 'vocabulary', '阅读', '閱讀'}
EXERCISES = {'task', 'tasks', 'exercise', 'exercises', 'quiz', 'instruction',
             'instructions', 'directions', 'translation'}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    raw = token.strip()
    word = raw.lstrip('._(/=-').lower()
    doc = prefix.document_ids[-1]
    prev = '' if carry is None or carry[0] != doc else carry[1]
    definite = float(prev in DEFINITE)
    value = 0.0
    if word in {'option', 'options'}:
        value = 0.94 if token.startswith(' ') else 0.68
        if word == 'options':
            value += 0.30
        value += (0.60 if word == 'options' else 0.35) * definite
        if raw.isupper() or raw != raw.lstrip('._(/=-'):
            value = 0.80
    elif word in {'question', 'questions'}:
        value = 0.58 + 0.36 * definite
        if raw == 'Question':
            value = 0.78
        elif raw == 'Questions':
            value = 0.42 if token.startswith(' ') else 0.76
    elif word in {'prompt', 'prompts', 'rompt'}:
        value = 0.50 + 0.40 * definite
    elif word in {'passage', 'passages', 'blank', 'blanks'}:
        value = 1.05 + 0.60 * definite
        if word == 'blanks':
            value = 1.55 + 0.90 * definite
        elif word == 'passages':
            value = 0.88 + 0.20 * definite
        elif word == 'blank' and not token.startswith(' '):
            value = 0.45
    elif word == 'comprehension':
        value = 2.40 if prev == 'reading' else 0.85
    elif word == 'preh' and prev in {'com', 'miscom'}:
        value = 0.90  # The first part of split 'comprehension'.
    elif word == 'ension' and prev == 'preh':
        value = 1.80
    elif word in {'选项', '選項'}:
        value = 1.45
    elif word in {'对话', '對話'}:
        value = 0.94
    elif word in DIALOGUE:
        value = 0.73 if word == 'dialogue' else 0.54
    elif word in {'choice', 'choices', 'possibility', 'possibilities'}:
        value = 0.50 if word.endswith('s') else 0.25
    elif word in READING_UNITS:
        value = 0.40
    elif word in EXERCISES:
        value = 0.26
    elif word == 'following' and prev == 'the':
        value = 0.24
    elif word == 'text':
        value = 0.15 if token.startswith(' ') else 0.03
    elif raw == 'Test' and token.startswith(' '):
        value = 0.13
    return (doc, word), value

"""A lexical tightness detector, with negative activation.

Chinese 'tight' gives the largest pulse. Tightness compounds, English
'tight' inflections, and close packing, urgency and tension give weaker
pulses. Recognize completed byte-split characters and split forms of
'tight', 'tightness', 'compactness', and 'strictness'.
Values are rounded training estimates, not sentence-level interpretation.
Everything else is zero: this deliberately omits weak lexical responses.
"""
READS = ()

TIGHT_COMPOUNDS = {
    '紧密': -3.9, '紧急': -3.9, '紧紧': -3.5,
    '紧凑': -2.5, '抓紧': -2.3, '加紧': -2.5,
    '紧迫': -2.0, '紧跟': -2.0, '紧接着': -1.7, '紧张': -1.6,
}
GROUPS = (
    (-1.9, {'密', '密集'}),
    (-1.7, {'急', 'urgently'}),
    (-1.45, {'urgent'}),
    (-1.2, {'closely', 'dense', 'densely', '忙', '急忙'}),
    (-1.0, {'compact', 'emergency', 'urgency', '密切', '严格'}),
    (-0.85, {'worry'}),
    (-0.7, {'tension', 'tense', 'firmly', 'snug'}),
    (-0.55, {'strict', 'secure', 'loose', 'intense'}),
)
WORDS = {w: v for v, group in GROUPS for w in group}
WORDS.update(TIGHT_COMPOUNDS)


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    same_doc = (prefix.position > 0 and
                prefix.document_ids[-2] == prefix.document_ids[-1])
    if '\ufffd' in word and same_doc:
        word = prefix.text_prefixes[-1][-1:]
    previous = prefix.token_strings[-2].strip().lower() if same_doc else ''
    if word == '紧':
        value = -6.2
    elif word == '緊':
        value = -5.65
    elif word == 'tight':
        value = -3.0
    elif word in {'tightly', 'tighter', 'tighten'}:
        value = -2.3
    elif word in {'tightened', 'tightening'}:
        value = -1.8
    elif word == 'ight' and previous.strip('-/_') == 't':
        value = -1.6
    elif word == 'ness' and previous in {'tight', 'compact', 'strict'}:
        value = -1.8 if previous == 'tight' else -0.6
    else:
        value = WORDS.get(word, 0.0)
    return None, float(value)

programs.haiku:
"""Tightness, closeness, urgency and tension word detector (layers.0.mlp.down_proj:3912).

The component is sparse and mostly negative: it dips on words for being tight, tense,
closely packed, urgent or strictly controlled, and sits near zero on almost every other
token. The program looks at the current word and returns a fixed negative value for its
class (roughly that class's typical activation in the data), and 0 otherwise.
  - tight family (tight, tightly, tighter, tighten)            about -3
  - Chinese 紧 / 緊 (tight, urgent) and its compounds           -6 to -0.6 by word
  - closely, dense, compact                                    about -1
  - urgent, urgency, emergency, 急 (urgent), 忙 (busy)          about -1 to -1.7
  - tension, tense, worry, intense                             about -0.8
  - strict, stringent, secure, firmly, 严 (strict), 牢 (firm)   about -0.5 to -1
  - loose, loosely, 松 (loose): the opposite end, about -0.5
"""

TIGHT = {"tight": -3.0, "tighter": -2.2, "tightest": -2.2, "tightly": -2.4, "tighten": -2.2,
         "tightened": -1.8, "tightening": -1.8}
CLOSE = {"closely": -1.2, "dense": -1.1, "densely": -1.2, "compact": -1.0, "compressed": -0.5,
         "compress": -0.4, "compression": -0.4}
URGENT = {"urgent": -1.5, "urgently": -1.7, "urgency": -1.0, "emergency": -0.9,
          "immediate": -0.4, "immediately": -0.4, "pressing": -0.4, "frantic": -0.4}
TENSE = {"tension": -0.8, "tensions": -0.5, "tense": -0.7, "worry": -0.8, "worries": -0.45,
         "worrying": -0.45, "intense": -0.6, "intensely": -0.7, "intensity": -0.3}
STRICT = {"strict": -0.5, "stricter": -0.6, "stringent": -0.7, "rigorous": -0.4,
          "intricate": -0.5, "secure": -0.45, "securely": -0.56, "firmly": -0.67}
