programs.sol:
"""Approximate Markdown boundary responses using tokens and distances.

Hash-only tokens stand in for heading prefixes. Their pulse depends on hash
count and document position. Following line breaks can give negative pulses,
fading with intervening tokens and lines. Bold endings and horizontal rules
have separate responses; block-comment punctuation is not treated as bold.
Nearby inline hash fragments weaken heading responses. Ordinary tokens are
zero. State resets at each document boundary.
"""
import math

READS = ()
INITIAL_HASH_PULSE = (0, .055, 2.410, 11.338, 1.695, 1.744, 1.620)
# By heading depth: response strength and decay length, in tokens.
SINGLE = ((0, 1), (.073, 16), (.62, 9), (.82, 14),
          (.72, 17), (.61, 10), (.27, 25))
BLANK = ((0, 1), (.47, 24), (1.17, 15), (1.34, 32),
         (1.49, 19), (.96, 29), (.81, 12))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, 0, 1000, 0, "", False, 1000)
    (_, position, level, distance, breaks, previous,
     starts_heading, inline_age) = carry
    s = prefix.token_strings[-1]
    mark = s.strip()
    hashes = bool(mark) and set(mark) == {"#"}
    value = 0.0
    inline_age += 1
    if "#" in s and not hashes:
        inline_age = 0
    if position == 0:
        starts_heading = hashes
    if hashes and "\n" not in s:
        n = len(mark)
        level, distance, breaks = (n if n <= 6 else 0), 0, 0
        if position == 0:
            value = INITIAL_HASH_PULSE[n] if n <= 6 else 0.0
            if s != mark:
                value = .93 if n == 2 else 0.0
        elif n == 3:
            value = .24 + 2.65 / math.sqrt(position + 1)
            value -= .18 * starts_heading
            value += .43 * previous.endswith("\\n")
            if s != mark:
                value = .24
        elif 4 <= n <= 6:
            value = .22 + .8 / math.sqrt(position + 1)
            if n == 5:
                value += .15
        elif n == 2:
            value = .10 if s != mark else -.03
            value += .19 * previous.endswith("\\n")
        elif n == 1:
            value = -.02
    else:
        distance += 1

    if hashes and inline_age < 10:
        value *= .6

    count = s.count("\n")
    if count:
        blank = count == 2
        strength, length = (BLANK if blank else SINGLE)[level]
        response = strength * math.exp(-distance / length) * .8 ** breaks
        if count > 2:
            response *= .2
        if inline_age < 16 and level >= 2:
            response *= .5
        factor = 1.0
        if mark:
            factor = .75 if blank else .5
            if "." in mark:
                factor = .6 if blank else .1
            elif "+" in mark or "#" in mark:
                factor = 1.0 if blank else 0.0
        if "*" in mark and "/" in mark:
            value = 0.0  # Code comments are not bold titles.
        elif "**" in mark:
            value = -.8 if blank else -.3 - 1.5 * response
        elif mark and set(mark) == {"-"} and len(mark) >= 3:
            value = -.4 if blank else -.05
        else:
            value -= factor * response
            if blank:
                value -= .01
                if "`" in mark:
                    value -= .10
        breaks += 1

    state = (doc, position + 1, level, distance, breaks, s,
             starts_heading, inline_age)
    return state, float(value)

programs.luna:
"""Give Markdown heading markers a small positive signal and their following
line break a small negative signal."""
READS = ()


def is_heading(line):
    stripped = line.lstrip()
    marks = len(stripped) - len(stripped.lstrip("#"))
    if 1 <= marks <= 6:
        rest = stripped[marks:]
        if not rest or rest[0].isspace():
            return True
    return stripped.startswith("**")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    line = "" if carry is None or carry[0] != doc else carry[1]

    marker = token.strip()
    if marker and marker.strip("#") == "" and len(marker) <= 6:
        value = 0.2
    elif "\n" in token and is_heading(line):
        value = -0.4
    else:
        value = 0.0

    new_line = (line + token).rsplit("\n", 1)[-1]
    return (doc, new_line), value

programs.sol:
"""Markets versus dependence: a sparse, multilingual spelling detector.

Market words are positive; dependence/reliance words are negative, especially
bare Chinese 依. English identifier punctuation is ignored. Remembering one
word catches split 'depend-ence' and a weaker response to its following
preposition. Formatting words and Chinese superlative 最 are smaller positives.
Everything else is zero; this is not a general topic classifier.
"""
READS = ()

DEPEND_VERBS = {'depend', 'depends', 'depending', 'dependencies'}
RELIANCE = {'rely', 'relies', 'reliance', 'relying'}
CHINESE_BASIS = {'依法', '依照', '依托', '依靠', '依据', '倚'}
CHINESE_RELIANCE = {'依赖', '依賴', '依然', '依旧', '依舊', '依據'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    raw = prefix.token_strings[-1]
    word = raw.strip().lower().lstrip('_-.=')
    value = 0.0
    if word == '依':
        value = -5.8
    elif word in CHINESE_BASIS:
        value = -1.9
    elif word in CHINESE_RELIANCE:
        value = -1.2
    elif word in {'靠', '凭', '憑', '凭借', '憑藉'}:
        value = -0.7
    elif word in {'市场', '市场的'}:
        value = 2.15
    elif word == '市場':
        value = 1.65
    elif word.endswith(('市场', '市場')) or word in {'市场上', '市場上'}:
        value = 1.7
    elif word.startswith(('市场', '市場')):
        value = 0.85
    elif word in {'market', 'markets'}:
        value = 1.55
    elif word in {'marketplace', 'marketplaces'}:
        value = 0.95
    elif word in {'marketing', 'marketed'}:
        value = 0.32
    elif word in {'mercado', 'mercados', 'السوق'}:
        value = 0.7
    elif word == 'рын':  # Russian root for market, before its inflection.
        value = 1.1
    elif word in DEPEND_VERBS:
        value = -1.05
    elif word == 'dependency':
        value = -1.2
    elif word == 'dependence':
        value = -0.93
    elif word in {'dependent', 'depended'}:
        value = -0.65
    elif word in RELIANCE:
        value = -0.5
    elif word.startswith('завис'):  # Russian dependence word family.
        value = -0.65
    elif previous == 'depend' and word in {'ence', 'ency', 'encies'}:
        value = -0.95
    elif previous in DEPEND_VERBS | {'dependency', 'dependence'}:
        if word in {'on', 'of', 'upon'}:
            value = -0.3
    if word in {'format', 'formats'}:
        value = 0.35
    elif word in {'最', '中最'}:
        value = 0.69
    return (doc, word), value

