"""Mark market vocabulary positively and dependency vocabulary negatively.

High-impact examples include English and Chinese words for markets, and
words for dependence. This small lexical rule leaves other tokens at zero.
"""

READS = ()

MARKETS = {"market", "markets", "市场", "市場"}
DEPENDENCE = {
    "depend", "depends", "depending", "dependent", "dependence",
    "dependency", "reliance", "靠", "依據", "依赖", "依賴", "依靠",
}


