programs.sol:
"""Negative pulses on plus symbols and short doubled-p spellings.

Training activations concentrate on +, ++, pp/PP and C++-style spellings.
This approximation uses whitespace, case, attached punctuation and the previous
same-document token to set pulse size. Ordinary arithmetic-looking operands
weaken a plus; quotes, empty call parentheses and newlines can strengthen it.
Short pp fragments, PHP, opposition words and doubled punctuation have smaller
responses. Everything else is zero: this recognizes spellings, not sums.
"""
READS: tuple[str, ...] = ()


def predict(token, previous):
    bare = token.strip()
    spaced = token.startswith(' ')
    # Written plus and increment signs.
    if '++' in token:
        if '{' in token:
            return -1.1
        if ')' in token and ';' in token:
            return -3.0
        if ')' in token or ';' in token or '[' in token:
            return -2.6
        if token.count('+') >= 4:
            return -2.2
        if token.count('+') == 3:
            return -3.1 if spaced else -4.1
        if '\n' in token:
            return -3.0 if spaced else -3.6
        if previous.strip().lower() == 'c':
            return -4.35
        return -4.4 if spaced else -4.8
    if '+' in token or '＋' in token:
        if '=' in token:
            return -1.1
        if '\n' in token:
            return -0.9
        if bare not in ('+', '＋'):
            if spaced or any(c in token for c in "\"'"):
                return -0.85
            if token == ')+':
                return -0.75
            return -1.05
        left = previous.strip()
        if '\n' in previous:
            return -1.4 if not spaced else -0.85
        if any(c in previous for c in "\"'"):
            return -1.1 if spaced else -1.3
        if left and left.isnumeric() and not left.isdecimal():
            return -0.6 if spaced else -0.95
        if left.endswith('()'):
            return -1.05 if spaced else -1.5
        variable = left.lstrip('(_^*')
        arithmetic = (left.isdecimal() or
                      (len(variable) == 1 and variable.isalpha()) or
                      (left and left[-1] in ')]}'))
        if arithmetic:
            return -0.7 if spaced else -1.02
        return -0.85 if spaced else -1.23
    # Doubled-p fragments and programming-language/file spellings.
    if bare.lower() == 'pp':
        if bare.islower():
            return -4.3 if spaced else -4.8
        return -3.75 if spaced else -4.5
    if bare.lstrip('_').lower() == 'pp':
        return -3.6
    if bare.lstrip('_/').lower() == 'cpp':
        if bare.startswith('/'):
            return -2.5
        if bare == 'Cpp':
            return -4.8
        if bare.islower():
            return -3.4
        return -3.8 if spaced else -4.2
    if bare.lower() in ('.cpp', '.hpp', '_hpp'):
        return -1.8
    word = bare.lower().lstrip('_')
    if len(word) == 3 and 'pp' in word and word != 'app':
        # Short doubled-p fragments, not the ordinary word 'app'.
        return -1.6
    if bare.lstrip('./').lower() == 'php':
        if bare.startswith('.'):
            return -0.25
        if bare == 'php' and previous.rstrip().endswith('_'):
            return -1.6
        if bare[0].isupper():
            return -0.75 if spaced else -0.6
        return -0.8 if spaced else -1.2
    # Smaller collateral responses on opposition and repeated punctuation.
    if bare.lower() == 'opposite':
        return -1.05
    if bare.lower().startswith('oppon') or bare.lower() == 'opposing':
        return -0.65
    if bare == '^^':
        return -1.5
    if bare == '!!':
        return -0.6
    if bare == '--' and not spaced:
        return -0.3
    if '--' in token and any(c in token for c in ';)'):
        return -1.2
    return 0.0


def step(carry, prefix, upstream):
    previous = ''
    if len(prefix.token_ids) > 1:
        if prefix.document_ids[-1] == prefix.document_ids[-2]:
            previous = prefix.token_strings[-2]
    return None, predict(prefix.token_strings[-1], previous)

