"""Concept program for layers.0.mlp.down_proj:3920.

The component fires when the text is about operating a control: pressing a key
or button, switching or turning something on or off, activating / enabling /
triggering it, and the input, mode, light and signal words around such devices.
Its strongest case is "press" (pressed, pressing). "on"/"off" only count right
after a switch-or-turn verb ("switch on", "turned off"). Everything else is
near zero.
"""
PRESS = {"press", "pressed", "pressing", "presses"}
SWITCH = {"switch", "switched", "switches", "switching", "turn", "turned", "turns", "turning", "toggle"}
ACTIVATE = {"activate", "activated", "activating", "activation", "activates", "enable", "enabled",
            "enabling", "enables", "disable", "disabled", "trigger", "triggered", "triggers",
            "override", "detect", "detected", "detecting", "engage", "engaged", "initiate"}
DEVICE = {"button", "buttons", "key", "keys", "keycode", "keydown", "input", "inputs", "mode", "modes",
          "light", "lights", "illumination", "signal", "ignition", "switch", "state", "dial", "control"}
MOTION = {"down", "start", "starts", "started", "open", "opens", "opened", "close", "closed", "enter"}
READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    before = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
