    if word in ("on", "off"):
        return carry, 1.6 if before in SWITCH else 0.1
    if word in SWITCH or word in ACTIVATE:
        return carry, 0.5
    if word in DEVICE:
        return carry, 0.4
    if word in MOTION:
        return carry, 0.2
