programs.luna:
"""Approximate a sparse detector for commands and system states.

It looks at the current word, including words embedded in code identifiers.
Commands get a stronger response than names for states, controls, and directions.
"""
import re

READS = ()

ACTIONS = {
    "press", "enter", "click", "start", "stop", "enable", "disable",
    "activate", "deactivate", "trigger", "load", "quit", "close",
    "open", "draw", "set", "turn", "fire", "move", "select", "shut",
    "shutdown", "check", "connect", "engage", "awaken", "act",
}
CONTROLS = {
    "state", "mode", "status", "on", "off", "up", "down", "input",
    "output", "signal", "trigger", "alarm", "key", "button", "switch",
    "time", "timeout", "activation", "sound",
}


def word_parts(token):
    # Split camel case and all-caps names such as .isOn and _MODE.
    return re.findall(r"[A-Z]+(?=[A-Z][a-z]|\b)|[A-Z]?[a-z]+|[0-9]+", token)


def step(carry, prefix, upstream):
    words = {part.lower() for part in word_parts(prefix.token_strings[-1])}
    # Recognize common English inflections of an action or control word.
    roots = set(words)
    for word in words:
        if word.endswith("ies") and len(word) > 4:
            roots.add(word[:-3] + "y")
        for ending in ("es", "s", "ed", "ing"):
            if word.endswith(ending) and len(word) > len(ending) + 2:
                stem = word[:-len(ending)]
                roots.add(stem)
                roots.add(stem + "e")

    if roots & ACTIONS:
        return None, 0.10
    if roots & CONTROLS:
        return None, 0.07
    return None, 0.0

programs.sol:
"""Predict the first word of a bracketed aside, not the whole aside.

Separate opening punctuation produces a positive pulse on the next word.
Explanatory connectives get the largest pulse; names and ordinary words get
less, and numbers do not. Tokenization matters: a space or a newline after
the bracket suppresses the pulse. The familiar abbreviations e.g. and i.e.
can produce a second pulse on their second token. One lowercase word
continuation receives a small pulse; an em-dash-prefixed word receives a
medium one. Away from these onsets, 'then' and opening reasoning/tool-result
tags receive small positive predictions. State resets between documents.
The rules approximate the pattern, not every token's lexical idiosyncrasies.
"""

READS = ()
OPEN = set('([{（［｛<【')
STRONG = set('and but which where including such for with that'.split())
CONNECTIVES = set('as or so since except like though because although if '
                  'unless also assuming based possibly especially whether maybe'.split())
GRAMMAR = set('in from by of to without given each both when while using excluding could '
              'should it we they you who most'.split())
CODE_WORDS = set('int long float char byte string list dict array node var '
                 'self data count value len max min sqrt sin cos log exp'.split())
CJK_ASIDES = set('含 如 注 以下 本文 例如 即 或 其中 包括'.split())


def word_pulse(word):
    low = word.lower()
    if word in CJK_ASIDES:
        return 1.9
    if not word:
        return -0.10
    if word.isdigit():
        return -0.11
    if word and set(word) == {'='}:
        return 1.30
    if word and set(word) == {'*'}:
        return 0.65
    if word in {'#', '@', '^', '?', '<'}:
        return 0.75
    if not word[0].isalpha():
        return 0.0
    if word in {'FIG', 'Fig'}:
        return 1.32
    if word.isupper() and len(word) > 1:
        return 0.20
    if low in STRONG:
        return 2.05
    if low == 'the':
        return 1.67
    if low in {'not', 'at', 'on'}:
        return 1.03
    if low == 'there':
        return 1.65
    if word in {'What', 'How', 'Why', 'Who', 'When', 'Where'}:
        return 2.05
    if word == 'I':
        return 0.65
    if low in CONNECTIVES:
        return 1.85 if word.istitle() else 1.50
    if low in GRAMMAR:
        return 1.65 if word.istitle() else 1.20
    if low == 'see':
        return 1.80 if word.istitle() else 0.93
    if low in {'this', 'your', 'all', 'note'}:
        return 1.65 if word.istitle() else 0.75
    if word in {'Figure', 'Table', 'Eq', 'Section'}:
        return 1.10
    if word.islower() and len(word) > 1 and set(word) <= set('ivxlcdm'):
        return 0.10
    if low in CODE_WORDS:
        return 0.22 if word.islower() else 0.55
    if all(c in '一二三四五六七八九十百千万零两' for c in word):
        return 1.30
    if all('\u3400' <= c <= '\u9fff' for c in word):
        return 0.80
    if word.islower() and word.endswith('ly'):
        return 0.90
    if word.islower() and word.endswith('ing'):
        return 0.65
    if len(word) == 1:
        return 0.44 if word.isupper() else 0.07
    return 0.70 if word[0].isupper() else 0.42


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous, began = ('', False)
    if carry is not None and carry[0] == doc:
        _, previous, began = carry
    value = 0.001
    if token.strip().lower() == 'then':
        value = 0.16
    elif token in {'<tool_response>', '<think>'}:
        value = 0.17
    opening = previous[-1:] in OPEN
    if opening:
        value = word_pulse(token)
        if token[:1].isspace():
            value = -0.14
        elif previous.endswith(('{', '｛')):
            value *= 0.20
        elif previous.endswith('<'):
            value *= 0.55
        elif previous.endswith(('[', '［')):
            if token.isdigit():
                value = -0.02
            elif len(token) == 1 and token.isalpha():
                value += 0.22
    elif began and (previous, token) in {('e', '.g'), ('i', '.e')}:
        value = 1.02
    elif began and token[:1].islower() and previous[-1:].isalpha():
        value = 0.12
    elif token.startswith('—') and token[1:].isalpha():
        value = 0.55
    if carry is None or carry[0] != doc:
        if token in {'(', '（'}:
            value = 0.95
    return (doc, token, opening), float(value)

programs.haiku:
"""Opening-bracket asides in prose.

Layer-0 MLP unit 3921 fires on the first word inside an opening bracket "(", "（" or "[",
i.e. on the start of a parenthetical aside: "... the sum (which is ...)",
"... they define it (and ...)", "... the number (for ...)". It is strongest when the
aside opens with a clause-linking word (which, that, and, for, since, such, the, ...),
weaker for an ordinary word or name, and near zero for a single variable "(x)",
a digit, an acronym "(CAP)", or other code/math. On the bracket token itself and
elsewhere it is ~0.
"""

READS = ()

OPENERS = {"(", " (", "（", "[", " [", "((", " ((", ".(", "{(", "([", " ([", '"(', "“(", '"['}

CLAUSE_WORDS = {
    "which", "that", "who", "whom", "whose", "where", "when", "since", "because",
    "as", "so", "and", "or", "but", "for", "with", "including", "such", "also",
    "the", "The", "in", "like", "see", "Fig", "Figure", "In", "For", "This", "There",
}


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    if len(toks) < 2:
        return None, 0.0
    prev, cur = toks[-2], toks[-1]
    word = cur.strip()
    if prev in OPENERS:
        if word in CLAUSE_WORDS:
            return None, 1.6
        if len(word) >= 2 and word.isalpha() and not word.isupper():
            return None, 0.6
        if word.isdigit():
            return None, -0.1
        if len(word) == 1 and word.isalpha():
            return None, 0.25
        return None, 0.1
    if prev in {"e", "i"} and cur in {".g", ".e"} and len(toks) > 2 and toks[-3] in OPENERS:
        return None, 1.0
    return None, 0.0

