"""Approximate a sparse response at the start of a bracketed aside.

An alphabetic token just inside an opening delimiter gets a positive pulse;
common connective and explanatory starters get a larger pulse. Elsewhere it
predicts zero, except for a small negative value on non-word bracket contents.
"""
READS = ()

OPENERS = frozenset("([{（［｛")
ASIDE_STARTERS = frozenset({
    "and", "or", "but", "which", "that", "who", "where", "when",
    "whose", "if", "as", "because", "since", "while", "though",
    "although", "unless", "whether", "for", "with", "in", "of",
    "to", "by", "from", "not", "also", "including", "especially",
    "see",
})


def step(carry, prefix, upstream):
    if len(prefix) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0
    previous = prefix.token_strings[-2].rstrip()
    current = prefix.token_strings[-1].strip()
