SUFFIXES = frozenset('''
ing ed ly er est s es tion ation ion ity ment ness able ible al ic
ous ive en ent ary ory ish ian ism ist ize ise ization isation
ance ence ington ford wood son sen ton berg burg ley land well
worth ville field dale brook
'''.split())
CLUSTER = re.compile(r'^[aeiou]+[bcdfghjklmnpqrstvwxz]{2,}[aeiouy]')
TAIL = re.compile(r'[A-Za-z]+$')
RARE_NAME_PIECES = frozenset(('olland', 'askell', 'iesel'))
FAMILIAR_COMPLETIONS = frozenset(('holland', 'haskell', 'diesel'))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, previous = '', ''
    else:
        _, tail, previous = carry
    s = prefix.token_strings[-1]
    value = -0.0005
    if s.isascii() and s.isalpha() and s.islower():
        n = len(s)
        if s not in SUFFIXES:
            if n >= 4 and s[0] in VOWELS:
                if len(tail) == 1:
                    value = -0.065 if tail.isupper() else -0.035
                    if CLUSTER.match(s):
                        value *= 1.35
                elif len(tail) == 0:
                    value = -0.023
                elif len(tail) == 2:
                    value = -0.010
            elif n >= 4 and len(tail) == 1:
                value = -0.021
            elif n <= 3 and not tail:
                value = 0.014
        if s in RARE_NAME_PIECES:
            if previous and len(tail) <= 1:
                value = -0.65
            elif len(tail) == 2:
                value = -0.12
            if (tail + s).lower() in FAMILIAR_COMPLETIONS:
                value = -0.06
        if previous.endswith('://') and n <= 4:
            value = 0.11
    match = TAIL.search(s)
    if match:
        tail = (tail + s if match.start() == 0 else match[0])[-30:]
    else:
        tail = ''
    return (doc, tail, s), float(value)

