"""Predict local letter joins inside words, especially clusters involving r/l.

Joins like b|r, f|l and pr|a get strong positive values, attenuated for
longer token pieces. Other vowel/consonant and nasal joins are weaker.
Consonants after an unfinished liquid cluster receive a negative value.
Spaces, punctuation and document boundaries break the join. Accent removal
and letter classes extend the same heuristic to Cyrillic and Greek.
"""
import unicodedata

READS = ()
VOWELS = set('aeiouy')
LIQUIDS = set('rl')
STRONG = set('bcfghkpqv')
WEAK = set('dtsz')
CONSONANTS = STRONG | WEAK | set('jmnrlwx')
CYRILLIC = dict(zip('абвгдезийклмнопрстуфхцыэяёю',
                    'abvgdeziyklmnoprstufhcieyeu'))
CYRILLIC.update({'ж': 'h', 'ш': 'h', 'ч': 'h', 'і': 'i', 'є': 'e'})
GREEK = dict(zip('αβγδεζηθικλμνξοπρστυφχψω',
                 'abgdezehiklmnxoprstufhpo'))
LATIN = {'ł': 'l', 'ø': 'o', 'æ': 'a', 'œ': 'o', 'ß': 's', 'ſ': 's'}


def letter(c):
    c = ''.join(x for x in unicodedata.normalize('NFD', c.lower())
                if not unicodedata.combining(x))[:1]
    return CYRILLIC.get(c, GREEK.get(c, LATIN.get(c, c)))


def join_value(previous, token):
    if not (previous and token and previous[-1].isalpha()
            and token[0].isalpha()):
        return 0.0
    last, penult, first = map(
        letter, (previous[-1], previous[-2:-1], token[0]))
    n = len(token)
    cluster = last in LIQUIDS and penult in CONSONANTS

    if first in LIQUIDS:
        if last in STRONG:
            if n <= 2:
                return 1.0
            if n == 3:
                return 0.8
            return 0.57 if n == 4 else 0.30
        return (0.43 if n <= 3 else 0.16) if last in WEAK else -0.01
    if cluster and first in CONSONANTS:
        return -0.20
    if last in LIQUIDS and first in VOWELS:
        if cluster:
            onset = all(letter(c) in CONSONANTS for c in previous.strip())
            if onset and n <= 3:
                return 1.0 if last == 'r' else 0.69
            return 0.46 if n <= 4 else 0.20
        if penult in VOWELS:
            return 0.10
        return 0.57 if n <= 3 else 0.35
    if first in CONSONANTS:
        if n > 2:
            return 0.11 if first in 'mn' else 0.02
        if last in VOWELS:
            return 0.39 if last in 'ou' else 0.22
        return 0.23 if first in 'mn' else 0.04
    if first in VOWELS:
        if penult in VOWELS:
            return -0.07
        return 0.07 if last in 'mn' else -0.03
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == document else ''
    return (document, token), float(join_value(previous, token))

