ROMANCE_FUNCTION_WORDS = frozenset(
    "de la el que en y los las por con una para es di il che e della gli le do da dos das "
    "um uma é não com se non sono un al est les des du une qui o os na no como pero más "
    "su sus ma anche alla nel dal sul ha hay muy también".split()
)
ENGLISH_FUNCTION_WORDS = frozenset(
    "the of and is to that with for are this by was as be it on or an which from at not "
    "have has you your can will".split()
)

# Token -> activation when the text is Romance (roughly its size in the data).
CONTRACTED_DE = {"del": -1.4, "Del": -1.4, "do": -1.4, "dell": -1.1, "della": -0.6,
                 "delle": -0.6, "dei": -0.6, "dos": -0.5, "da": -0.4, "das": -0.25}
CONTRACTED_A = {"al": -0.55, "Al": -0.6, "all": -0.45, "alla": -0.5, "dal": -0.5,
                "nel": -0.5}
ARTICLES = {"un": -0.5, "una": -0.1, "no": -0.6, "l": -0.27, "el": -0.17}
PER_WORDS = {"per": 0.6, "io": 0.45, "te": 0.25}
VALUE = {**CONTRACTED_DE, **CONTRACTED_A, **ARTICLES, **PER_WORDS}


def _word(prefix):
    return prefix.token_strings[-1]


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
