"""A first-operand response after an arithmetic sign.

Addition activates strongly on digits and variable letters, and less on other
term beginnings. Lower-valued initial digits respond more strongly.
Subtraction and numeric ranges are weaker. A separate blank absorbs part of
the response; later digits have a rapidly decaying response.
The string-conversion function `str` is a strong concatenation operand.
State resets whenever the packed input changes documents.
"""
READS = ()
NUMBER_BASE = {'+': 4.15, '＋': 3.3, '-': 0.85,
               '−': 0.97, '–': 0.67, '±': 1.17}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    sign, scale, gap, tail = (
        carry[1:] if carry and carry[0] == doc else ('', 1.0, '', 0.0)
    )
    text = prefix.token_strings[-1]
    w = text.strip()
    digit = bool(w) and w[0].isdecimal()
    variable = len(w) == 1 and w.isalpha()
    addition = sign in ('+', '＋')
    value = tail if digit else 0.0
    if sign:
        if digit:
            slope = 0.12 if addition else 0.035
            value = NUMBER_BASE[sign] - slope * int(w[0])
            if addition and gap:
                value -= 0.55 if gap == ' ' else 2.0
        elif addition:
            if not w:
                value = 1.05 if text == ' ' else 0.55
            elif variable:
                value = 2.2 + 0.55 * (text == w) if w.isascii() else 1.4
            elif w == 'str':
                value = 5.2
            else:
                value = -0.25 if w.startswith('+') else 0.9
            if gap:
                value *= 0.2
        elif variable:
            value = {'−': 0.37, '±': 0.65}.get(sign, 0.17)
            if gap:
                value *= 0.2
        elif w and w[0].isalpha():
            value = -0.06
        value *= scale
    tail = 0.1 * value if digit and text == w else 0.0
    if len(w) == 2 and w[0] == '+' and w[1].isalpha():
        value += 0.85
    if w:
        sign = w[-1] if w[-1] in NUMBER_BASE else ''
        scale = 1.0
        for ending, factor in (('+=', 0.4), ('++', 0.5), ('+(', 0.4)):
            if w.endswith(ending):
                sign, scale = '+', factor
                break
        if '\n' in text:
            scale *= 0.25
        gap = ''
    elif gap or '\n' in text:
        sign = ''
    else:
        gap = text
    return (doc, sign, scale, gap, tail), float(value)

