"""Token-local detector of broad horizontal blanks (spaces or tabs).

The response rises steeply from roughly 15 to 28 columns, stays high around
30 columns, and tapers for wider padding. Tabs count as about four spaces.
Blank spans ending in a newline use an earlier-rising response curve.
Text, newline-only tokens, and embedded line breaks are predicted as zero.
"""
READS = ()


def interpolate(x, points):
    for (lo, a), (hi, b) in zip(points, points[1:]):
        if x <= hi:
            return a + (b - a) * max(0.0, x - lo) / (hi - lo)
    return points[-1][1]


