    token = prefix.token_strings[-1]
    if not token or token.strip(" \t\r\n"):
        return None, 0.0
    body = token.rstrip("\r\n")
    if not body or "\n" in body or "\r" in body:
        return None, 0.0
    spaces = body.count(" ")
    tabs = body.count("\t")
    width = spaces + 4 * tabs
    if body != token:
        value = interpolate(width, ((0, 0), (12, .10), (19, .49),
                                    (21, .81), (27, 1.14), (32, 1.25),
                                    (49, .70)))
    else:
        if tabs and not spaces:
            width += 2
        value = interpolate(width, ((0, 0), (4, .01), (15, -.03),
                                    (19, .33), (28, 1.28), (35, 1.25),
                                    (64, .50)))
        # Long padding mixing tabs and spaces has a stronger response.
        if tabs and spaces:
            value += .03 * min(8, max(0, width - 23))
    return None, value

