READS = ()

PERSONAL = {'i', 'we', 'you', 'he', 'she', 'it', 'they'}
POSSESSIVE = {'my', 'your', 'his', 'her', 'its', 'our', 'their'}
DEMONSTRATIVE = {'this', 'that', 'these', 'those'}
AUXILIARY = {
    'is', 'was', 'were', 'been',
    'do', 'does', 'did', 'can', 'could', 'will', 'would',
    'should', 'may', 'might', 'must', 'have', 'has', 'had',
}
REFERENCE = {
    'shown', 'seen', 'stated', 'indicated', 'mentioned', 'observed',
    'depicted', 'suggested', 'noted',
}
PASSIVE = {
    'known', 'given', 'found', 'written', 'taken', 'done',
    'understood',
}

PROCEDURAL = {
    'required', 'needed', 'desired', 'requested', 'intended', 'planned',
    'specified', 'computed', 'measured', 'discussed', 'compared', 'defined',
    'reported', 'demonstrated', 'distinguished', 'opposed', 'illustrated',
    'promised', 'published', 'advertised', 'evidenced', 'applied', 'used',
    'determined', 'provided', 'amended', 'alleged',
}


def response(token):
    """Approximate signed response to an 'as' continuation, by word class."""
    w = token.strip().lower()
    if not token.startswith((' ', '\t')) and w.isalpha():
        return 0.0
    if token.strip().istitle() and w != 'i':
        return 0.0
    if w == 'the':
        return 1.8
    if w in {'a', 'an'}:
        return 0.2 if w == 'a' else 0.0
    if w in POSSESSIVE or w in DEMONSTRATIVE:
        return 1.2
    if w in PERSONAL:
        return -3.0 if w == 'you' else -2.3 if w == 'we' else -1.7
    if w in {'if', 'though', 'per'}:
        return -4.3
    if w in REFERENCE:
        return -4.4
    if w == 'described':
        return -3.8
    if w == 'expected':
        return -2.65
    if w in PASSIVE or w in PROCEDURAL:
        return -2.9
    if w in {'soon', 'ever', 'always', 'previously', 'usual'}:
        return -4.1
    if w in {'before', 'above', 'long', 'far', 'in'}:
        return -3.1
    if w in {'already', 'surely'}:
        return -2.5
    if w in {'well', 'much', 'many'}:
        return -2.45
    if w in AUXILIARY or w in {'of', 'with', 'when'}:
        return -2.0
    if w == 'regards':
        return -3.0
    if w in {'part', 'for', 'necessary', 'last', 'early', 'earlier'}:
        return -1.7
    if w in {'any', 'possible', 'there', 'other', 'several'}:
        return -1.1
    if w == 'to':
        return -0.3
    if w == 'follows':
        return -0.95
    if token in {' ', '\t'}:
        return 0.85
    if w and w[0] in "\"'“‘:([{":
        return 0.75
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, before = '', ''
    else:
        previous, before = carry[1:]
    token = prefix.token_strings[-1]
    w = token.strip().lower()
    prev = previous.strip().lower()
    value = 0.0
    r = response(token)
    if prev == 'as':
        value = r
        if previous.strip() == 'As' and w == 'the':
            value += 0.4
    elif prev == 'like':
        value = r * (0.9 if w in DEMONSTRATIVE else 0.5)
        if w in PERSONAL:
            value = -1.4 if w != 'you' else -2.0
    elif prev == 'than':
        value = r * (0.2 if r > 0 else 0.5)
        if w in {'others', 'most', 'any', 'other', 'usual', 'ever', 'before'}:
            value = -1.6
        elif w in {'just', 'or'}:
            value = -1.1
        elif w in {'that', 'those'}:
            value = 0.0
        elif w in PERSONAL:
            value = -1.3
    elif prev == 'what':
        value = r * 0.2
        if w == 'a':
            value = -0.6
    elif before.strip().lower() == 'as':
        value = r * 0.2
    if token.strip() == '{"':
        value = 0.32
    return (doc, token, previous), float(value)

programs.haiku:
"""Layer-0 MLP down-projection component 3932: the word after "as".

The component is quiet almost everywhere. Its large values sit on the word right after
"as" (any capitalisation), and the sign depends on what kind of word that is:

- a determiner or possessive ("as the", "as this", "as their"): positive, most for "the";
- a quote or opening bracket: mildly positive;
- "a" / "an": about zero;
- a past participle ("as shown", "as expected", "as described"): strongly negative;
- a pronoun or auxiliary ("as you", "as we", "as it", "as is"): negative;
- a conjunction, adverb or preposition ("as well", "as if", "as soon", "as long",
  "as far", "as much", "as of"): strongly negative;
- anything else ("as to", "as possible", "as follows"): slightly negative.

The word after "like" follows the same rule at 0.6 strength, and the word after "than"
at 0.5 strength. Everywhere else the prediction is 0.
"""

READS = ()

AS_WORDS = {"as"}
THAN_WORDS = {"than"}
LIKE_WORDS = {"like"}

DETERMINERS = {
    "the": 1.8, "this": 1.3, "that": 1.2, "these": 0.8, "those": 0.6,
    "his": 1.3, "her": 1.0, "their": 1.4, "my": 1.3, "its": 1.0,
    "our": 1.2, "your": 1.0, "both": 0.9,
}
QUOTES = {'"', "“", "(", "'"}
ARTICLES = {"a": 0.25, "an": 0.1}

PARTICIPLES = {"shown", "seen", "known", "given", "done", "made", "taken", "stated"}
PRONOUNS_AUX = {
    "i", "you", "we", "it", "they", "he", "she", "there",
    "is", "was", "were", "are", "be", "will", "can", "do", "did", "does", "has", "had",
}
# Clause-starting conjunctions, adverbs and prepositions that follow "as".
CONJ_ADVERBS = {
    "well", "if", "soon", "long", "far", "before", "though", "much", "many",
    "when", "ever", "always", "per", "in", "of", "for", "with", "since",
}

WEIGHT = {"participle": -3.0, "pronoun": -1.9, "conjunction": -2.75, "other": -0.2}
THAN_SCALE = 0.5
LIKE_SCALE = 0.6


def after_as(word):
    """The value of the word that follows "as", by its kind."""
    if word in DETERMINERS:
        return DETERMINERS[word]
    if word in ARTICLES:
        return ARTICLES[word]
    if word in PARTICIPLES or (len(word) > 3 and word.endswith("ed")):
        return WEIGHT["participle"]
    if word in PRONOUNS_AUX:
        return WEIGHT["pronoun"]
    if word in CONJ_ADVERBS:
        return WEIGHT["conjunction"]
    return WEIGHT["other"]


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    docs = prefix.document_ids
    if len(tokens) < 2 or docs[-1] != docs[-2]:
        return carry, 0.0
    prev = tokens[-2].strip().lower()
    cur = tokens[-1].strip()
    if cur in QUOTES:
        word_value = 0.7
    else:
        word_value = after_as(cur.lower())
    if prev in AS_WORDS:
        return carry, word_value
    if prev in THAN_WORDS:
        return carry, THAN_SCALE * word_value
    if prev in LIKE_WORDS:
        return carry, LIKE_SCALE * word_value
    return carry, 0.0

programs.sol:
"""Detect written forms of eight, plus the reasoning-boundary markers.

The digit 8 dominates. Its strength varies with the preceding character:
letters boost it, while a decimal point or another 8 weakens it. English
number words, Chinese 八, Roman VIII, and August also give positive signals.
Other tokens get zero; their smaller, idiosyncratic responses are omitted.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    initial = (prefix.position == 0 or
               prefix.document_ids[-1] != prefix.document_ids[-2])
    previous = '' if initial else prefix.token_strings[-2]
    last = previous[-1:]

    if word == '8':
        if initial:
            value = 1.06
        elif last == '8' or previous == '.':
            value = 0.84
        elif last and last in '0123456789':
            value = 0.99 if int(last) % 2 else 0.90
        elif last.isalpha():
            value = 1.17
        elif last.isspace():
            value = 0.92
        else:
            value = 0.95
    elif word == '８':
        value = 0.94
    elif word == '八':
        value = 1.49
    elif word == '第八':
        value = 1.22
    elif '八' in word:
        value = 0.70
    elif word.lstrip('-').lower() in {'eight', 'eighth'}:
        value = 0.89 if token[:1].isspace() else 0.78
    elif word.lower() == 'eighty':
        value = 0.76
    elif word.lower() == 'eighteen':
        value = 0.55
    elif word == 'VIII':
        value = 0.48
    elif word == 'August':
        value = 0.59 if token[:1].isspace() else 0.48
    elif word == 'Aug':
        value = 0.43 if token[:1].isspace() else 0.25
    elif token == '</think>':
        value = 0.71
    elif token == '<think>':
        value = 0.14
    else:
        value = 0.0
    return None, value

