"""Estimate activations on frequent grammatical word pieces in several scripts.

The clearest responses are to English be/been and Japanese case particles,
especially standalone を. A few German function words and the URL separator
are weaker examples. Everything else is treated as inactive.
"""

READS = ()

ENGLISH_AUXILIARIES = {" be", " been"}
GERMAN_FORMS = {" einen", " werden", " wurde"}
JAPANESE_PARTICLES = {"を", "に", "が", "で", "について", "にて", "から"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == "を":
        return None, -11.0
    if "を" in token:
