programs.haiku:
"""Layer-0 MLP component down_proj:3937: a German-grammar detector.

What it does: it writes a positive value on German articles, determiners and pronouns
(die, eine, alle, welche, seine ...) and on German adjective endings (-liche, -ische,
-ende); a negative value on the noun-forming suffix -ung (and -ungen/-ungs), on other
German noun fragments (-lag, -uch, -anz, Natur), and on the prepositions zu, aus, nach,
von. These are scaled by how German the text looks so far (a running count of German
versus English function words, reset at each document), so the same word is ignored in
English text (where the activation is about zero).

The prediction is the word-class weight times the German-context gate. A dictionary of
every token would explain more, but these classes are what a reader can follow.
"""

READS = ()

GERMAN_WORDS = {
    "der", "die", "das", "und", "ist", "nicht", "ein", "eine", "zu", "mit", "sich", "auch",
    "für", "von", "dem", "den", "des", "im", "werden", "sind", "auf", "sie", "wir", "aber",
    "wird", "hat", "dass", "ich", "er", "es", "als", "bei", "nach",
}
ENGLISH_WORDS = {
    "the", "and", "of", "is", "to", "with", "that", "it", "for", "on", "are", "this", "was",
    "as", "be", "by", "from", "have", "which", "or", "an", "at",
}
DECAY = 0.98  # how fast the German-context score forgets older words

ARTICLES = {
    "die", "das", "eine", "ein", "einer", "einen", "einem", "alle", "welche", "diese",
    "dieses", "jede", "jedes", "keine", "seine", "ihre", "beide", "einige", "sind", "werden",
    "ihn", "sie", "wir", "sein", "waren", "dieser", "diesem", "jeder", "jeden", "mehr",
    "andere", "anderen", "solche", "manche", "welcher", "welches",
}
DER = {"der"}  # weaker than the other articles
ADJ_ENDINGS = {
    "liche", "lichen", "licher", "ische", "ischen", "ischer", "ige", "ste", "te", "ere",
    "ende", "enden", "gende", "erte", "ierte", "che", "ches",
}
NOUN_FRAGMENTS = {"lag", "uch", "anz", "atur", "ucht", "heit", "igkeit", "natur", "art",
                  "hand", "uck", "ug", "gang", "ß", "z", "zen", "bar", "ut"}
PREPOSITIONS = {"zu", "aus", "nach", "von", "um", "vor", "ab", "bis", "durch", "an"}
FUER = {"für", "im"}


def word_value(word):
    """The class weight of one token (its text, stripped and lower-cased)."""
    if word.endswith("ung") or word.endswith("ungen") or word.endswith("ungs"):
        return -1.9
    if word in ARTICLES:
        return 1.2
    if word == "es":
        return 0.5
    if word in DER:
        return 0.5
    if word in ADJ_ENDINGS:
        return 1.3
    if word in NOUN_FRAGMENTS:
        return -0.95
    if word in PREPOSITIONS:
        return -0.8
    if word in FUER:
        return 0.3
    return 0.0


def step(carry, prefix, upstream):
    # carry: (German-context score, document id of the last token)
    if carry is None or carry[1] != prefix.document_ids[-1]:
        german = 0.0  # a new document starts with no context
    else:
        german = carry[0]
    word = prefix.token_strings[-1].strip().lower()
    german = DECAY * german + (word in GERMAN_WORDS) - (word in ENGLISH_WORDS)
    gate = min(max(german * 0.5, 0.0), 1.0)  # 0 in English, 1 in clearly German text
    return (german, prefix.document_ids[-1]), word_value(word) * gate

programs.luna:
"""A small surface-form sketch of a German-word feature. It predicts
negative values for -ung nouns and positive values for German determiners
and some adjective endings; other tokens get zero."""
READS = ()

DETERMINERS_AND_WORDS = {
    "die": 1.15, "das": 0.9, "der": 0.5,
    "eine": 1.7, "einer": 0.8, "einen": 1.1,
    "ein": 0.9, "einem": 0.45, "eines": 0.6,
    "alle": 1.25, "alles": 1.2, "andere": 1.7,
    "jeder": 0.8, "einige": 1.0,
    "welche": 1.7, "diese": 1.5,
    "sie": 0.95, "wir": 1.2, "sind": 0.9, "werden": 0.9,
    "für": 0.45,
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()

    # Frequent German noun endings. The bare -ung token is especially strong.
    if word == "ung":
        return None, -1.9
    if word.endswith("ungen"):
        return None, -1.2
    if word.endswith("ungs"):
        return None, -1.6
    if word.endswith("ung"):
        return None, -0.6
    if word.endswith("heit"):
        return None, -0.8
    if word.endswith("keit"):
        return None, -0.9

    # German adjective endings, with weaker values for the longer inflections.
    if word.endswith("liche") or word.endswith("ische"):
        return None, 2.0
    if word.endswith("lichen") or word.endswith("ischen"):
        return None, 1.2
    if word.endswith(("licher", "liches", "ischer", "isches")):
        return None, 0.9
    if word.endswith("ende"):
        return None, 1.0
    if word.endswith("enden"):
        return None, 0.8
    if word.endswith("chen") or word.endswith("igen"):
        return None, 0.3

    if word in {"ä", "ö"}:
        return None, 0.24
    value = DETERMINERS_AND_WORDS.get(word, 0.0)
    if word == "zu":
        value -= 0.9
    elif word == "nach":
        value -= 0.7
    elif word == "aus":
        value -= 0.55
    elif word == "von":
        value -= 0.5
    elif word == "vor":
        value -= 0.65
    elif word == "ß":
        value -= 0.65
    return None, float(value)

programs.sol:
"""Detect square roots and weaker elementary mathematical notation.

The strongest matches are radicals, sqrt (including its qrt fragment), and
'square root'. Root words, functions, Greek variable names, TeX commands,
powers and check marks give smaller responses. These capture the large
training activations without memorizing general-text token effects.
A short, document-reset text suffix distinguishes TeX and Greek prose and
recognizes a little spillover onto the token immediately after a root.
Unmatched tokens receive zero.
"""
READS = ()
GREEK_NAMES = set('alpha beta gamma delta epsilon zeta eta theta iota kappa '
                  'lambda mu nu xi omicron rho sigma tau upsilon phi chi '
                  'psi omega'.split())
GREEK_LETTERS = set('αβγδεζηθικλμνξοπρσςτυφχψωΓΔΘΛΞΠΣΦΨΩ')
FUNCTIONS = {
    'sin': 1.0, 'cos': 1.05, 'tan': 0.55, 'cot': 0.6,
    'ln': 1.25, 'log': 0.35, 'exp': 0.2, 'pow': 0.4,
    'floor': 0.9, 'ceil': 0.75, 'abs': 0.5,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail, previous_value = ('', 0.0)
    same_document = carry is not None and carry[0] == doc
    if same_document:
        _, tail, previous_value = carry
    token = prefix.token_strings[-1]
    s = token.strip()
    name = s.lstrip('._-(/\\$[').lower()
    latex = tail.endswith('\\')
    attached = bool(tail and tail[-1].isalpha() and not token[:1].isspace())
    value = 0.0

    if '√' in s:
        value = 8.9
    elif name == 'sqrt':
        value = 8.9 if latex else (8.7 if s.startswith('.') else 7.9)
    elif name == 'qrt':
        # The tokenizer can split sqrt into s + qrt; a row may start at qrt.
        value = 8.45 if not tail or tail.lower().endswith('s') else 6.0
    elif '\ufffd' in s:
        # Decoding the prefix recovers a radical split inside its UTF-8 bytes.
        ending = prefix.text_prefixes[-1][-1:] if same_document else ''
        if ending == '√':
            value = 11.2
        elif ending == '∛':
            value = 3.3
    elif name in {'root', 'roots'}:
        if tail.lower().endswith('square'):
            value = 5.0 if name == 'roots' else 5.55
        elif tail.lower().endswith('cube'):
            value = 2.6
        else:
            value = 0.95 if name == 'roots' else 1.15
    elif name == 'irrational':
        value = 1.35
    elif s in {'根', 'кор'}:
        value = 0.9  # Chinese and Russian root words/fragments.
    elif name in FUNCTIONS:
        value = FUNCTIONS[name]
        if latex:
            value += 0.45
        elif s.startswith('.') and name != 'log':
            value += 0.7
        elif attached:
            value *= 0.4
    elif name == 'pi':
        value = 1.7 if latex else (0.6 if attached else 1.05)
    elif name in GREEK_NAMES:
        value = 0.6
    elif s in GREEK_LETTERS:
        # A letter inside a Greek word is not a mathematical variable.
        greek_word = bool(tail and tail[-1] in GREEK_LETTERS)
        greek_word |= sum('\u0370' <= c <= '\u03ff' or
                          '\u1f00' <= c <= '\u1fff' for c in tail) >= 3
        value = 0.12 if greek_word else (1.5 if s == 'π' else 0.6)
    elif s == 'frac':
        value = 1.45 if latex or tail.endswith('d') else 0.65
    elif s in {'boxed', 'hat', 'cal', 'bb', 'tilde', 'ilde', 'symbol'}:
        if latex or tail.endswith(('math', 'bold')):
            value = 1.5 if s == 'boxed' else 0.6
    elif name in {'square', 'squares', 'squared', 'squ'}:
        value = 0.6 if name in {'squared', 'squ'} else 0.43
    elif s in {'²', '³', '±', 'µ'}:
        value = 0.53
    elif s in {'✓', '✔'}:
        value = 1.1
    elif s == '∫':
        value = 0.7
    elif s == '∂':
        value = 0.4
    elif s in {'(', '{'} and previous_value > 6.0:
        value = 1.0 if s == '{' else 0.8
    elif (s == 'of' and previous_value > 4.0
          and tail.lower().endswith(('root', 'roots'))):
        value = 1.7 if tail.lower().endswith('roots') else 2.0

    return (doc, (tail + token)[-24:], value), float(value)

programs.haiku:
"""Square-root detector (layers.0.mlp.down_proj, component 3939).

What it does: this component writes a large signal into the residual stream at the
square-root sign. It is nearly silent on almost every token, but on the square-root sign
"√" (about 9 as a single token, about 11 when the sign is split into UTF-8 bytes, where it
is completed by its last byte) and on the word "sqrt" (about 8) it is very strong. It is
weaker (about 0.5 to 1.2) on related maths notation: root words, fractions, floor and
ceiling, the boxed/tick answer marks, trig and log names, powers, and Greek letters.

How the program reads it: it only looks at the newest token and the decoded text so far.
"""

READS = ()

SQRT_WORDS = {"sqrt", " sqrt", "Sqrt", " Sqrt", "qrt", ".sqrt", "_sqrt"}

ROOT_WORDS = {
    "root", " root", "roots", " roots", "Root", " Root", "ROOT", "_root", "(root", "-root",
    "frac", "floor", ".floor", " floor", "ceil", ".ceil", " ceil",
    "boxed", "✓", " ✓", "✔",
}

TRIG_LOG = {"sin", " sin", "cos", " cos", "tan", " tan", "log", " log", "ln", " ln", "/log"}

GREEK = {
    "π", " π", "pi", " pi", "(pi", "α", " α", "θ", "λ", "β", " β", "γ", " γ",
    "δ", " δ", "σ", "τ", "µ", " µ", "μ", "theta", "eta", "sigma", "tau", "lambda",
    "gamma", "delta", "mu",
}

POWER = {"²", "³", "squared", "_squared", " squared", " square", "square"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    now = prefix.text_prefixes[-1]
    before = prefix.text_prefixes[-2] if len(prefix) > 1 else ""
    if tok == "√":
        return None, 8.8
    if now.endswith("√") and not before.endswith("√"):
        # the sign was split into bytes; this token completes it
        return None, 11.3
    if tok in SQRT_WORDS or (now.endswith("sqrt") and not before.endswith("sqrt")):
        return None, 8.3
    if tok in ROOT_WORDS:
        return None, 1.2
    if tok in TRIG_LOG or tok in GREEK:
        return None, 0.6
    if tok in POWER:
        return None, 0.5
    return None, 0.0

