"""Recognize pieces of mathematical notation, especially square roots."""
import unicodedata

READS = ()

_WORDS = {
    "sqrt", "root", "roots", "frac", "sin", "cos", "tan", "ceil", "floor",
    "ln", "irrational", "boxed",
    "alpha", "beta", "gamma", "delta", "epsilon", "theta", "lambda",
    "mu", "pi", "rho", "sigma", "tau", "phi", "psi", "omega",
}


