programs.sol:
"""A partial spelling-boundary explanation, not a lexical lookup table.

Remember the preceding token's alphabetic tail, resetting between documents.
Unspaced hyphens are positive after short vowel-consonant spellings, uppercase
fragments and listed word prefixes. Letter continuations receive smaller
spelling scores: labial endings, velar or uncommon onsets, and doubling raise
them; liquid onsets lower them. These are fitted spelling heuristics, not a
pronunciation model. Idiosyncratic responses to individual tokens are omitted.
"""

READS = ()
VOWELS = frozenset('aeiouy')
CONSONANTS = frozenset('bcdfghjklmnpqrstvwxz')
HYPHENS = frozenset('-\xad‐‑')
PREFIXES = frozenset({
    'ab', 'ad', 'al', 'anti', 'co', 'com', 'con', 'de', 'dis',
    'ex', 'im', 'in', 'inter', 'mid', 'non', 'over', 'post',
    'pre', 'pro', 're', 'sub', 'super', 'trans', 'un', 'under',
})
BOUND_PREFIXES = frozenset({
    'ab', 'ad', 'af', 'ag', 'al', 'am', 'an', 'ap', 'ar', 'as',
    'at', 'com', 'con', 'cor', 'im', 'in', 'il', 'ir', 'ob', 'oc',
    'of', 'op', 'sub', 'suc', 'suf', 'sug', 'sup', 'sus', 'dis',
    'un', 'mid',
})


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    state = (doc, token)
    start = len(previous)
    while start and previous[start - 1].isalpha():
        start -= 1
    word = previous[start:]
    if not word or not token or token[0].isspace() or not word.isalpha():
        return state, 0.0
    lower = word.lower()
    final = lower[-1]
    closed = (len(word) >= 2 and final in CONSONANTS
              and lower[-2] in VOWELS)
    digraphs = {'ch', 'ck', 'gh', 'ng', 'ph', 'sh', 'th'}
    if len(word) >= 3 and lower[-2:] in digraphs:
        closed = lower[-3] in VOWELS

    if token[0] in HYPHENS:
        separate = token.strip() in HYPHENS
        if not separate:
            value = 0.020 if closed else 0.0
            if final in VOWELS:
                value -= 0.030
            if lower in PREFIXES:
                value += 0.015
            return state, value
        value = 0.11
        if previous[0].isspace():
            value += 0.06
        if closed and len(word) <= 5:
            value += 0.18
        if word.isupper() and closed:
            value += 0.08
        if lower in PREFIXES:
            value += 0.06
        if lower in BOUND_PREFIXES:
            value += 0.19
        if final in 'aei':
            value -= 0.05
        elif final in 'bmpv':
            value += 0.05
        elif final == 'n':
            value -= 0.07
        elif final in 'rsx':
            value -= 0.025
        return state, value

    first = token[0].lower()
    if token.isalpha() and token.isascii() and word.isascii():
        if first in CONSONANTS:
            if closed and len(word) <= 3:
                value = 0.050
                if final in 'bmpfv':       # labial consonants
                    value += 0.032
                elif final in 'dnrw':      # frequent endings and glides
                    value -= 0.033
                if first in 'gkq':        # velar stops
                    value += 0.043
                elif first in 'jxz':      # uncommon English consonant onsets
                    value += 0.081
                elif first in 'lr':       # liquids readily extend a cluster
                    value -= 0.068
                elif first in 'cdhmnps':
                    value -= 0.038
                if final == first:
                    value += 0.033
                    if len(word) == 2 and final in 'bgkmpf':
                        value += 0.058
                if len(word) == 2 and final in 'bmpfv' and first in 'gkqjxz':
                    value += 0.074
                if lower[-2] in 'ai':
                    value += 0.026
                elif lower[-2] in 'ey':
                    value -= 0.024
                if previous[0].isspace():
                    value += 0.029
                return state, value
            return state, -0.015 if len(word) >= 5 else 0.0
        if first in VOWELS:
            return state, -0.010 if closed and len(word) <= 3 else 0.010
    return state, 0.0

