"""Respond to small grammatical phrases carried by a single token.

Chinese personal-pronoun-plus-predicate tokens get the largest values;
bare pronouns, possessives, reflexives and noun/topic bundles are weaker.
Japanese noun-plus-particle tokens, Korean subject pronouns, English
reflexives and Romance first-person-plural endings are additional cases.
Small backgrounds depend on Chinese/Japanese token length. The rule is
token-local: it does not recover contextual variation or every lexical case.
"""
READS = ()

PERSONAL = set('我你他她它您')
PLURAL = set('们們')
INSTITUTIONS = set('国國市省校院军軍方队隊')
MODALS = {'会', '會', '能', '要', '将', '將', '可以', '需要', '应该', '應該'}
STATES = {'在', '不', '没', '沒', '没有', '沒有', '不是', '很', '曾'}
THOUGHT = {'想', '看', '觉得', '覺得', '喜欢', '喜歡'}
PEOPLE = {'人', '人们', '人們', '们', '們', '大家', '自己'}
BUSINESSES = {'公司', '企业', '企業', '客户', '客戶', '用户', '用戶'}
EVIDENCE = {'数据', '資料', '资料', '报告', '報告', '调查', '調查', '结果', '結果'}
NEWS = {'媒体', '媒體', '消息', '记者', '記者', '新闻', '新聞'}
TOPICS = {'中国', '中國', '全球', '世界', '社会', '社會', '经济', '經濟',
          '市场', '市場', '人才', '政府', '国家', '國家', '人民', '党', '黨'}
PREDICATES = {'在', '为', '為', '都', '说', '說', '有', '能', '会', '會', '要',
              '显示', '顯示', '表明', '提供', '需求', '发展', '發展', '管理',
              '体验', '體驗', '报道', '報道', '采访', '採訪', '称', '稱',
              '培养', '培養', '增长', '增長', '建设', '建設', '服务', '服務', '竞争'}
SUBJECTS = sorted(PEOPLE | BUSINESSES | EVIDENCE | NEWS | TOPICS,
                  key=len, reverse=True)
JP_CASE = {'が': 1.9, 'は': 1.6, 'も': 2.2, 'に': 0.8,
           'と': 2.6, 'で': 0.8, 'を': 1.6, 'の': 0.5}
REFLEXIVES = {'myself', 'yourself', 'himself', 'herself', 'ourselves', 'yourselves'}
ROMANCE_WE_ENDINGS = {'amos', 'emos', 'imos', 'iamo', 'aremos', 'eremos', 'iremos'}
KO_SUBJECTS = {'나는', '내가', '우리는', '우리가', '제가', '저는'}


def all_han(s):
    return bool(s) and all('\u3400' <= c <= '\u9fff' for c in s)


def chinese(word):
    if word[0] in PERSONAL and len(word) > 1:
        tail = word[1:].lstrip('们們')
        if not tail:
            return 0.15
        if tail == '的':
            return 0.9 if any(c in PLURAL for c in word) or word[0] == '您' else 1.25
        if tail == '自己':
            return 4.7
        if tail == '人':
            return 0.28
        if tail in INSTITUTIONS:
            return 2.0
        if tail == '家':
            return 4.0
        if word[0] == '您':
            return 2.2 if tail == '好' else 5.0
        if word[0] == '它':
            return 4.8
        if tail in MODALS:
            return 6.1
        if tail in STATES:
            return 8.3
        if tail in THOUGHT:
            return 8.0
        return 6.9

    # Conditional/oblique introductions to a fused personal clause.
    for intro in ('如果', '对', '對', '跟', '为', '為'):
        if word.startswith(intro) and len(word) > len(intro):
            clause = word[len(intro):]
            if clause[0] in PERSONAL:
                floor = 1.2 if intro == '如果' else 0.1
                return max(floor, 0.55 * chinese(clause))

    for subject in SUBJECTS:
        if not word.startswith(subject) or len(word) == len(subject):
            continue
        tail = word[len(subject):]
        if tail == '的':
            return 0.3 if subject == '自己' else 1.0
        if tail in {'和', '与', '與'}:
            return 2.2
        if tail in PREDICATES or (subject == '大家' and tail in {'一起', '分享', '可以'}):
            if subject in BUSINESSES:
                return 5.6
            if subject in EVIDENCE or subject in NEWS:
                return 4.2
            if subject in PEOPLE:
                return 3.9 if tail == '都' else 4.7
            return 3.2
        if subject in TOPICS and len(tail) == 2:
            if subject == '人民' or tail == '主义':
                return 0.3
            return 2.0

    # Demonstrative subjects followed by a predicate, not a classifier.
    if word.startswith(('这', '那', '這')):
        if word[1:] in {'是', '就是', '也是', '不是', '只是', '才是'}:
            return 2.4 if len(word) == 2 else 3.1
        if word[1:] in {'就', '也', '让', '讓', '对', '對', '对于', '對於'}:
            return 3.5 if word[0] != '那' else 2.1
    if len(word) >= 3 and word.endswith(('人都', '们都', '們都')):
        return 3.6
    if (len(word) >= 3 or word.startswith('性')) and word[-1] in {'和', '与', '與'}:
        return 1.8
    if word.startswith('人') and len(word) > 1:
        return 0.75
    if word.startswith('的') and len(word) > 1:
        return -0.1
    return {1: -0.004, 2: 0.025, 3: 0.2}.get(len(word), 0.65)


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    low = word.lower()
    if low in REFLEXIVES or low == 'yours':
        return None, 0.96
    if low in {'themselves', 'oneself'}:
        return None, 0.59
    if low == 'itself':
        return None, 0.26
    if word in ROMANCE_WE_ENDINGS:
        return None, 0.85
    if word in KO_SUBJECTS:
        return None, 4.0
    if all_han(word):
        return None, float(chinese(word))

    # Japanese nouns/pronouns with a grammatical particle attached.
    if len(word) > 1 and word[-1] in JP_CASE:
        stem, particle = word[:-1], word[-1]
        if stem == '私':
            if particle == 'も':
                return None, 6.2
            return None, 1.7 if particle == 'の' else 4.4
        if stem == '自分':
            return None, 0.52 if particle == 'の' else 3.1
        if stem == '人':
            return None, {'が': 2.8, 'は': 2.2, 'も': 3.3, 'の': 0.75}.get(particle, 2.4)
        if stem in {'これ', 'それ', 'ここ', 'そこ'} and particle != 'の':
            return None, 2.6
        if (all_han(stem) and stem not in {'最', '何度'}) or stem in {'こと', 'もの', 'さん'}:
            return None, JP_CASE[particle]
    if 'ことができ' in word:
        return None, 1.8
    if word.endswith('です') and len(word) > 2:
        return None, 1.3
    kana = sum('\u3040' <= c <= '\u309f' for c in word)
    if kana:
        return None, 0.08 if len(word) == 2 else 0.15 if len(word) > 2 else 0.0
    return None, 0.0

