PRONOUN_START = "我你他她它私"              # subject pronouns that can start a fused token
BARE_PRONOUNS = {"我们", "你们", "他们", "她们", "我們", "你們", "他們",
                 "我", "你", "他", "她", "它", "私"}
NOT_A_PREDICATE = "的国家省人"              # possessive or noun after the pronoun: weak
KOREAN_SUBJECTS = {"나는", "내가", "저는", "제가", "우리는", "우리가"}
REFLEXIVES = {"himself", "herself", "itself", "themselves", "ourselves", "yourself", "myself"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    if word in REFLEXIVES:
        value = 0.5
    elif word in KOREAN_SUBJECTS:
        value = 4.0
    elif word in BARE_PRONOUNS or len(word) < 2:
        value = 0.0
    elif word[0] in PRONOUN_START:
        value = 1.0 if word[1] in NOT_A_PREDICATE else 6.0
    elif word[0] == "这" and word[1] in "是就对":
        value = 2.5
    elif word[0] == "人" and word[1] in "都心是":
        value = 4.0
    else:
        value = 0.0
    return carry, value

