    'lot': (-2.63, -2.55, .45), 'few': (-2.35, -1.50, 1.05),
    'couple': (-2.66, -3.60, 0.0), 'variety': (-2.58, -4.15, .40),
    'range': (-2.14, -3.60, -.05), 'result': (-2.35, -1.43, -.07),
    'little': (-1.47, -.70, .75), 'amount': (-1.72, -2.50, 0.0),
    'combination': (-1.49, -1.82, .10), 'series': (-1.05, -1.98, .05),
    'quarter': (-1.82, -1.80, .15), 'fraction': (-.80, -1.24, .50),
    'wide': (-1.31, -.54, 0.0), 'person': (-.90, -.54, 0.0),
