GROUPS = {'host', 'bunch', 'handful', 'plurality', 'quantity'}
COLLECTIONS = {'set', 'pair', 'group', 'collection', 'mixture', 'portion'}
ABUNDANCE = {'multitude', 'myriad', 'plethora', 'slew'}
COUNT = {'total', 'maximum', 'minimum', 'expected', 'count'}
PHRASES = {
    ('wide', 'range'): (-2.28, -2.20),
    ('wide', 'variety'): (-1.62, -2.20),
    ('wide', 'array'): (-1.15, -1.75),
    ('great', 'deal'): (-2.05, -1.12),
    ('little', 'bit'): (-1.93, -1.20),
    ('whole', 'lot'): (-1.56, -1.10),
    ('whole', 'bunch'): (-2.05, -1.60),
