        pulse, of_pulse = -1.50, -.54
    elif word in GROUPS:
        pulse, of_pulse = -1.70, -2.70
    elif word in COLLECTIONS:
        pulse, of_pulse = -.70, -1.50
    elif word in ABUNDANCE:
        pulse, of_pulse = -1.40, -2.40
    next_of = 1.1 if word == 'number' else .8 if word == 'fraction' else 0.0
    if last in ARTICLES:
        value = pulse
        next_of = of_pulse if word.isalpha() else 0.0
        if last in {'A', 'An'}:
            next_of *= .8
