"""Indefinite quantity phrases ("a lot of", "a couple of", "a wide range of", "any number of",
"as a result of") push this component negative: strongly on the quantity noun and on the "of"
that follows it, mildly on other "a X of" phrases. "the number of" pushes it positive."""
READS = ()

QUANTITY = {"lot", "couple", "variety", "range", "result", "number", "combination", "kind",
            "amount", "few", "quarter", "bunch", "handful", "dozen", "majority", "series",
            "pair", "bit", "type", "variant", "portion"}
INDEFINITE = {"a", "an", "any"}
DEFINITE = {"the"}

def step(carry, prefix, upstream):
    toks = [s.strip().lower() for s in prefix.token_strings]
    t = prefix.position
    cur = toks[t]
    back = toks[max(0, t - 3):t]          # up to three tokens before this one
    prev = toks[t - 1] if t >= 1 else ""
    indefinite = any(w in INDEFINITE for w in back)
    definite = any(w in DEFINITE for w in back)
    if cur in QUANTITY and indefinite:
        return carry, -2.0
    if cur == "of" and prev in QUANTITY and any(w in INDEFINITE for w in toks[max(0, t - 4):t]):
        return carry, -2.0
    if cur == "of" and indefinite and any(w in INDEFINITE for w in back[-2:]):
        return carry, -0.7
    if cur == "number" and definite:
        return carry, 1.5
    if cur == "of" and prev == "number" and definite:
        return carry, 1.8
    return carry, 0.0

