"""Recognize measure and partitive phrases, especially their completed heads."""
import re

READS = ()

# Heads of familiar quantity/partitive phrases and their signed response.
PHRASE_HEADS = {
    "lot": ("a", -2.4),
    "range": ("wide", -2.3),
    "variety": ("a", -2.5),
    "quarter": ("a", -1.8),
    "whole": ("a", -0.9),
    "result": ("a", -2.3),
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old_doc, tail = carry if carry is not None else (doc, "")
    if doc != old_doc:
        tail = ""

    token = prefix.token_strings[-1]
    # Only score a complete word carried by this token, not a mere word fragment.
    match = re.fullmatch(r"\s*([A-Za-z]+)[\s.,;:!?\"'()\[\]{}]*", token)
    word = match.group(1).lower() if match else ""
    previous = re.findall(r"[A-Za-z]+", tail.lower())
    value = 0.0

    if word in PHRASE_HEADS:
        modifier, strength = PHRASE_HEADS[word]
        if previous and previous[-1] == modifier:
            value = strength
    elif word == "few":
        value = -1.7 if previous and previous[-1] == "a" else 0.7
    elif word == "little":
        value = 0.8
    elif word == "fraction" and previous and previous[-1] == "what":
        value = 0.7
    elif word == "number" and previous and previous[-1] == "document":
        value = 1.0
    elif word == "of" and previous:
        head = previous[-1]
        if head == "number":
            # A definite number is a stated count; an indefinite or growing number
            # introduces an unspecified multitude.
            modifier = previous[-2] if len(previous) > 1 else ""
            if modifier in {"any", "growing", "increasing"}:
                value = -1.5
            elif modifier in {"the", "sheer"}:
                value = 1.0
        elif head == "couple" and len(previous) > 1 and previous[-2] == "a":
            value = -2.2
        elif head == "amount" and len(previous) > 1 and previous[-2] == "increasing":
            value = -1.6
        elif head == "combination" and len(previous) > 1 and previous[-2] == "a":
            value = -1.6
        elif head == "portion" and len(previous) > 1 and previous[-2] == "substantial":
            value = -1.6
        elif head in {"variety", "quarter", "whole", "result"}:
            if len(previous) > 1 and previous[-2] == "a":
                value = -1.6
        elif head == "range" and len(previous) > 1 and previous[-2] == "wide":
            value = -1.6
        elif head in {"kind", "type", "waste"}:
            if len(previous) > 1 and previous[-2] == "a":
                value = -1.6
        elif head == "problem" and len(previous) > 1 and previous[-2] == "the":
            value = -1.6
        elif head == "word" and len(previous) > 1 and previous[-2] == "variant":
            value = -1.0

    new_tail = (tail + token)[-120:]
    return (doc, new_tail), float(value)

