import unicodedata

READS = ()
SPATIAL_WORDS = frozenset('''
    local locally outside near nearby distant remote remotely
    inner outer inside internal internally external externally
'''.split())
GENDERED_PRONOUNS = frozenset('he him his himself she her hers herself'.split())


def spelling_response(token):
    bare = token.strip()
    if '®' in token:
        return -1.93 if bare == '®' else -1.42
    if bare == 'ï':
        return -1.73
    if bare == 'Ï':
        return -1.04
    if bare in {'ئ', 'ائ'}:
        return -0.58
    if bare == '™':
        return -0.28
    if bare == '°':
        return -0.115
    if bare and set(bare) == {'¯'}:
        return -0.9 / len(bare) ** 0.5
    if bare == '⎯':
        return -0.27
    if len(bare) == 1:
        decomposed = unicodedata.normalize('NFD', bare)
        if decomposed.lower().startswith('i') and len(decomposed) > 1:
            return -0.2 if '\u0302' in decomposed else -0.10
        if decomposed.lower() == 'e\u0308':
            return -0.18
