        return 0.0, 0.6 if n <= 3 else 0.25
    if q.endswith(('aw', 'ow')) or q == 'awa':
        return 0.0, 0.4
    if q.startswith('sh') or q.endswith('ash'):
        return (0.03, 0.6) if n <= 3 else (0.0, 0.2)
    if c in 'āōūäöőąłáóýıüéí':
        if c in 'éí':
            return -0.01, -0.2
        if c in 'āōū':
            return 0.02, 0.5
        return 0.0, 0.35
    if c in 'cxq':
        return 0.0, -0.4 if n <= 2 else -0.1
    if c == 'i':
        return 0.0, 0.0 if q.startswith('in') else -0.15
    if c in 'hn':
        return 0.0, 0.4 if n == 1 else 0.2
    if '\u0400' <= c <= '\u04ff':
        return (0.05, 0.6) if q == 'в' else (-0.008, 0.1)
    return -0.001, 0.02


def context_gain(s):
    q = s.strip().lower()
    if not q or s[-1].isspace():
        return 0.0
    if q.endswith(('k', 'к', 'ک')):
        if q.endswith('ck'):
            return 0.4
        return 0.85 if len(q) <= 3 else 0.25
    if q.endswith('w'):
        return 0.6 if len(q) <= 2 else 0.25
    if q.endswith(('sh', 'ш')):
        return 0.5 if len(q) <= 3 else 0.15
    if q.endswith(('z', 'з')):
        return 0.4 if len(q) <= 3 else 0.12
    if q.endswith(('h', 'y')) and len(q) <= 3:
        return 0.2
    return 0.0


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        q = s.strip().lower()
        if q in ('k', 'ok'):
            value = 0.85
        elif q in ('okay', 'w', 'sh', 'ash'):
            value = 0.4
        elif q == 'к':
            value = 0.31
        elif s.startswith('<|'):
            value = -0.13
        elif len(q) <= 3 and q.isalpha() and not s.strip().isupper():
            value = 0.5 if q.startswith('k') or q.endswith('k') else -0.05
        else:
            value = -0.05 if q.isalpha() else 0.0
    else:
        background, response = fragment(s)
        value = background + context_gain(carry[1]) * response
    return (doc, s), float(value)

programs.luna:
"""A sparse spelling heuristic for a starting K and continuations after k/к."""

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    reset = carry is None or carry[0] != doc
    history = "" if reset else carry[1]
    token = prefix.token_strings[-1]
    last = history[-1:] if history else ""

    # A lone capital K at a row/document reset is a separate strong cue.
    if reset and token == "K":
        value = 0.925
    # A few recognizable k-spellings have a stronger or opposite response.
    elif last == "k" and token[:1].islower():
        following = token[0].lower()
        value = {
            "k": 0.40, "n": 0.22, "h": 0.20, "w": 0.23,
            "o": 0.09, "a": 0.08,
            "i": -0.11, "e": -0.07, "c": -0.20,
        }.get(following, 0.05)
    elif last == "K" and token[:1].islower():
        value = 0.16 if token[0].lower() == "o" else 0.08
    elif last == "к" and token[:1].islower():
        value = 0.25 if token[0].lower() == "в" else 0.07
    elif last == "К" and token[:1].islower():
        value = 0.08
    else:
        value = 0.0

    return (doc, (history + token)[-8:]), value

programs.sol:
"""Alternative and inclusive expressions, with a strong response just after 'or'.

This lexical/short-phrase approximation gives most tokens zero. It recognizes
scope words, selected translations, and the first word introducing an
alternative. A few phrases retain the effect for one more token. Token spacing
and capitalization modulate the response to 'or'; document changes reset state.
It does not attempt to explain the component's smaller miscellaneous responses.
"""
READS = ()

SCOPE = {
    'all': 0.86, 'other': 0.95, 'another': 0.95, 'others': 0.86,
    'alternatively': 1.13, 'else': 0.65, 'otherwise': 0.28,
    'even': 0.50, 'simply': 0.44, 'something': 0.28,
    'whatever': 0.72, 'rather': 0.60, 'equivalent': 0.46,
    'someone': 0.23, 'just': 0.14, 'less': 0.11, 'least': 0.10,
}
# Non-English equivalents of even, other, all, and or.
TRANSLATIONS = {
    '甚': 0.95, '其他': 0.9, '他人': 0.84, '另一': 0.84,
    '或其他': 2.6, '全': 0.42, 'または': 1.4, '何か': 1.0,
    '他の': 0.63, 'или': 0.33, '或': 0.35, '或者': 0.9,
    'veya': 0.4, 'других': 0.43, 'все': 0.4, 'даже': 0.78,
    'anderen': 0.43, 'altro': 0.48, 'otro': 0.67,
    'başka': 0.83, 'même': 0.36,
}
EMPHASIS = {'even', 'simply', 'something', 'else', 'rather'}
POSSIBILITIES = {'perhaps', 'another', 'whatever', 'maybe'}
ALTERNATIVES = {'just', 'other', 'anything', 'alternatively', 'merely'}
INDEFINITES = {
    'something', 'anything', 'someone', 'somebody',
    'anyone', 'anybody', 'anywhere', 'somewhere',
}
MODALS = {'may', 'might', 'could'}
ARTICLES = {'a', 'an', 'the'}
PRONOUNS = {'it', 'you', 'we', 'they', 'its', 'your'}
AUXILIARIES = {
    'do', 'did', 'does', 'have', 'has', 'may', 'be', 'is', 'are', 'can', 'will',
}
PREPOSITIONS = {'in', 'to', 'at', 'of', 'as', 'through'}


def choice_response(word):
    """The word class at the beginning of an alternative."""
    if word in EMPHASIS:
        return 4.7
    if word in POSSIBILITIES:
        return 4.0
    if word in {'someone', 'somebody', 'ask'} or word.startswith('equival'):
        return 3.3
    if word in ALTERNATIVES:
        return 3.6
    if word in {'any', 'otherwise', 'possibly', 'what'}:
        return 2.9
    if word in (
        {'some', 'others', 'similar', 'sometimes', 'better', 'worse'} | INDEFINITES
    ):
        # Indefinite persons and places mark open-ended alternatives.
        return 2.5
    if word in ARTICLES:
        return 1.5 if word == 'the' else 1.95
    if word in PRONOUNS | AUXILIARIES | {'by', 'if', 'when', 'use', 'using', 'call'}:
        return 1.7
    if word in PREPOSITIONS | {'less', 'equal', 'two'}:
        return 1.35
    if word in {'all', 'both', 'false'}:
        return 2.0
    if word in {'more', 'not', 'with', 'for', 'on', 'from'}:
        return 0.85
    if word in {'and', 'or'}:
        return 0.0
    return 0.2 if len(word) >= 8 else 0.4


def step(carry, prefix, upstream):
    doc = int(prefix.document_ids[-1])
    raw = prefix.token_strings[-1]
    word = raw.strip().lower().strip('_.(/-—–')
    reset = carry is None or carry[0] != doc
    _, previous, strength, older_strength = (
        (doc, '', 0.0, 0.0) if reset else carry
    )
    value = SCOPE.get(word, TRANSLATIONS.get(word, 0.0))
    if word.startswith('equival'):
        value = 0.46
    if word.startswith('甚至'):
        value = 2.4
    if word == 'all' and raw == 'all':
        value = 0.62
    if word == 'else' and not raw.startswith(' '):
        value = 0.43

    if word == 'other':
        if previous == 'the':
            value = 0.63
        elif previous == 'each':
            value = 0.36
        elif previous in {'any', 'some'}:
            value = 1.6
    elif word == 'another' and previous == 'one':
        value = 0.60
    elif word == 'else' and previous in INDEFINITES:
        value = 1.1
    elif word == 'least' and previous == 'at':
        value = 0.27
    elif word == 'even':
        if previous in {'and', 'not', 'can'}:
            value = 1.0
        elif previous in MODALS:
            value = 1.4
        elif previous in {'maybe', 'perhaps'}:
            value = 2.5
    elif word in {'just', 'simply'} and previous == 'than':
        value = 1.1
    elif word == 'be':
        value = {
            'may': 0.35, 'could': 0.20, 'might': 0.20, 'can': -0.08,
        }.get(previous, 0.0)

    if strength:
        value = strength * choice_response(word)
    elif older_strength:
        # Short phrases with an introductory determiner, adverb, or auxiliary.
        if not previous:
            value = older_strength * 0.75 * choice_response(word)
        elif previous == ',':
            value += older_strength * 0.25 * choice_response(word)
        elif word == 'other' and previous in {'any', 'some', 'the'}:
            value = older_strength * (1.6 if previous == 'the' else 3.0)
        elif word == 'else' and previous in INDEFINITES:
            value = older_strength * 2.6
        elif word == 'least' and previous == 'at':
            value = older_strength * 2.1
        elif word in {'even', 'just'} and previous in {'perhaps', 'possibly', 'even'}:
            value = older_strength * (3.4 if word == 'even' else 2.5)
        elif word == 'be' and previous in MODALS | {'can'}:
            value = older_strength * (0.65 if previous == 'can' else 1.6)
        elif word in ARTICLES | {'of', 'any'} and previous in PREPOSITIONS | EMPHASIS:
            value += older_strength * 0.5

    # Equivalent alternative introductions in Russian, German, and Chinese.
    if previous in {'или', 'oder', '或', '或者'}:
        value += 0.4
        if word in {'даже', 'просто', '其它', '其他'}:
            value = 4.5
        elif word in {'же', '干脆', '是在'}:
            value = 3.6
        elif word in {'нет', 'auch', '在'}:
            value = 1.6
        if previous == '或' and word == '者':
            value = 4.8  # Completes the Chinese disjunction 或者 ('or').
    if previous == 'หร' and word.startswith('ือ'):
        value = 2.7  # Completes Thai หรือ ('or').
    if older_strength and previous.startswith('equival') and word == 'ently':
        value = 1.3  # Tokenized completion of 'or equivalently'.
    if reset and raw == ' or':
        value = 3.37

    # An attached lowercase 'or' is often only part of a longer word.
    new_strength = 0.0
    if word == 'or':
        new_strength = 1.0
        if raw == 'or':
            new_strength = 0.55
        elif raw == 'OR':
            new_strength = 0.35
        elif raw.strip() == 'OR':
            new_strength = 0.8
        elif raw.startswith('/'):
            new_strength = 0.5
    elif word == 'nor':
        new_strength = 0.7
    return (doc, word, new_strength, strength), float(value)

programs.haiku:
"""Fires on the word that continues an alternative introduced by "or": "or other",
"or even", "or another", "or something (else)", "or maybe", "or a", and so on. Its
strongest use is the word directly after "or"; a few words ("other", "else", "least") still
fire two or three tokens after "or" ("or any other", "or at least"). Weaker, context-free
versions of the same words ("all", "other", "alternatively") fire everywhere."""

READS = ()

# Words that introduce an alternative or a generality: strong directly after "or".
ALTERNATIVE = {"other", "others", "another", "even", "something", "anything", "whatever",
               "simply", "maybe", "perhaps", "else", "just", "any", "some", "all", "least",
               "甚至", "其他", "干脆", "даже", "просто"}
# Other words directly after "or" (a, the, you, by, ...) fire moderately.
FUNCTION = {"a", "an", "the", "of", "by", "in", "is", "to", "if", "at", "be", "you",
            "do", "have", "can", "will", "may"}
# Words that fire in the phrase "or any other", "or at least", "or something else".
NEAR_OR = {"other", "else", "least", "another"}
# Context-free weak senses.
WEAK = {"other": 0.9, "another": 0.9, "else": 0.6, "alternatively": 1.1, "all": 0.85,
        "whatever": 0.8, "even": 0.5, "simply": 0.5, "others": 0.9}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    doc = prefix.document_ids[-1]
    # Distance back to the nearest "or" in the same document, within three tokens.
    back = 0
    for k in range(2, 5):
        if len(prefix) < k or prefix.document_ids[-k] != doc:
            break
        if prefix.token_strings[-k].strip().lower() == "or":
            back = k - 1
            break
    if back == 1:
        if word in ALTERNATIVE:
            return carry, 4.0
        if word in FUNCTION:
            return carry, 1.5
        return carry, 0.3
    if back in (2, 3) and word in NEAR_OR:
        return carry, 2.0
    return carry, WEAK.get(word, 0.0)

programs.luna:
"""Recognize words that add or contrast alternatives and totals."""
READS = ()


def step(carry, prefix, upstream):
    """Approximate activations on words about inclusion or alternatives."""
    word = prefix.token_strings[-1].strip().casefold()
    if word in {"all", "even", "other", "another", "others", "alternatively"}:
        if word == "even":
            return None, 3.0
        if word == "all":
            return None, 0.9
        if word == "alternatively":
            return None, 1.1
        return None, 0.8
    return None, 0.0

programs.haiku:
"""Medium-family words. The component goes strongly negative on the word "medium"
(a middle size, degree or setting), and negative on "intermediate", "moderate",
"intermediary" and "media", more weakly on "mid" and "unknown"."""

READS = ()

# Levels: the activation predicted for each word, by how strongly it responds.
LEVELS = {
    -7.7: {"medium", "mediums"},
    -2.6: {"intermediate", "intermediary", "intermedi", "moderate", "moderately", "mediate"},
    -1.2: {"media", "mediatype", "medio", "medios", "媒", "媒体", "介", "中介", "中级"},
    -0.5: {"mid", "slightly", "unknown", "large"},
}
WORD_VALUE = {w: v for v, words in LEVELS.items() for w in words}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    return carry, WORD_VALUE.get(word, 0.0)

programs.luna:
"""Recognize the underscore joining an anonymized NAME to its number."""

READS = ()


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    if len(tokens) < 2:
        return None, 0.0

    # Do not join text across the model's document boundary.
    same_document = prefix.document_ids[-1] == prefix.document_ids[-2]
    if same_document and tokens[-1].strip() == "_":
        if tokens[-2].strip() == "NAME":
            return None, 0.7

    return None, 0.0

programs.haiku:
"""Draft 3: "by" after a past participle (passive agent, "X is governed by Y") fires
a bit more than "by" after a noun or a number ("2 by 2", "step by step")."""

READS = ()

PARTICIPLE_ENDINGS = ("ed", "en", "wn", "ht")
NUMBER_OR_STEP = ("step", "one", "two", "three", "2", "3", "4", "5", "6", "7", "8", "9")


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if tok.strip() == "by":
        if prev in NUMBER_OR_STEP:
            return None, 0.5
        if prev.endswith(PARTICIPLE_ENDINGS):
            return None, 1.5
        return None, 1.1
    if tok in ("-by", "_by"):
        return None, 1.2
    if tok.strip() == "little" and prev == "a":
        return None, 0.8
    return None, 0.0

programs.sol:
"""A lexical problem/issue detector, with graded responses.

'Issue(s)' is strongest, then 'problem(s)' and several translations. Errors,
bugs, trouble, matters, claims, concerns, and 'why' respond more weakly.
This is a spelling feature, including inflections and identifier fragments,
not a judgment that a passage describes a real problem. Case, plurality,
and path prefixes affect strength. The phrases 'issue of' and 'problem of'
continue responding on 'of'. A closing thinking tag gives a small response.
Unlisted words and the many small background activations are left at zero.
"""
READS = ()

WEAK_WORDS = {
    'bug', 'bugs', 'buggy', 'trouble', 'troubles', 'troublesome',
    'troubleshooting', 'concern', 'concerns', 'concerning', 'claim',
    'claims', 'why', 'flawed', 'inadequate', 'faulty',
}
DIFFICULTIES = {
    'concerned', 'defective', 'struggling', 'malfunction', 'deficiencies',
    'insufficient', 'shortcomings', 'complications', 'dispute', 'disputes',
    'claimed', 'claiming',
}
INCIDENTS = {'incident', 'incidents', 'crisis', 'crises', 'scandal',
             'allegations', 'shortage', 'shortages'}
OF_PHRASES = {'issue': 2.9, 'issues': 2.2, 'problem': 1.7,
              'problems': 1.4, 'matter': 0.5, 'question': 0.6}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    spelling = token.strip().lstrip('(_./-')
    word = spelling.lower()
    prev = previous.strip().lower()
    value = 0.0

    if word in {'issue', 'issues'}:
        if token == word and previous.endswith(('T', 't')):
            value = 0.7  # "issue" fragment in "tissue(s)"
        elif spelling[:1].isupper():
            value = 4.2
        elif token.startswith(' '):
            value = 4.85 if word == 'issue' else 4.6
        else:
            value = 4.0 if word == 'issue' else 3.5
    elif word in {'issued', 'issuing', 'issuance'}:
        value = 1.35 if word == 'issuance' else 2.25
        if token == 'issued':
            value = 1.3
    elif spelling in {'Iss', 'ISS'}:
        value = 1.0
    elif word in {'ue', 'ues'} and prev == 'iss':
        value = 2.9
    elif word.startswith(('probl', 'проблем')):
        value = 1.6 if word.endswith(('s', 'ы')) else 2.1
        if word not in {'problem', 'problems'}:
            value = 2.5 if 'è' in word else 1.85
        if spelling[:1].isupper():
            value = min(value, 1.8)
        if token.startswith('/'):
            value = 1.2
    elif word in {'blem', 'blems', 'ème', 'èmes'} and prev.endswith('pro'):
        value = 2.4 if 'blem' in word else 1.75
    elif word in {'error', 'errors', 'err', 'perror'}:
        value = 0.8 if word in {'error', 'perror'} else 0.65
        if spelling == 'Err':
            value = 0.9
        elif token == 'err':
            value = 0.35
    elif spelling.endswith('Error'):
        value = 0.85  # exception class names
    elif word in WEAK_WORDS:
        value = 0.67
    elif word in DIFFICULTIES:
        value = 0.4
    elif word in INCIDENTS:
        value = 0.6
    elif word in {'matter', 'matters'}:
        value = 1.0 if word == 'matters' else 0.8
        if prev == 'no':
            value = 0.25
    elif word in {'вопрос', 'вопросы'}:
        value = 1.05 if word == 'вопрос' else 0.55
    elif word.startswith('문제'):
        value = 2.8
    elif '问题' in token:
        value = 4.4 if token == '问题' else 3.7
        if token.startswith('解决'):
            value = 1.4
    elif '問題' in token:
        value = 3.3
    elif token.startswith('について'):
        value = 0.9
    elif token in {'に関して', '問い合わせ', 'トラブル'}:
        value = 0.75
    elif token in {'错误', '故障', '困扰', '危机', '为什么'}:
        value = 0.6
    elif token == '</think>':
        value = 0.5
    elif word == 'of':
        value = OF_PHRASES.get(prev, 0.0)

    return (doc, token), float(value)
